/* ---- 00-util.js ---- */
/* ---------- DOM helper ---------- */
// h('div.card', {style: {...}, onclick}, child, [children], 'text')
function h(tag, props, ...children) {
  let classes = [];
  let name = tag;
  const dot = tag.indexOf('.');
  if (dot >= 0) {
    name = tag.slice(0, dot) || 'div';
    classes = tag.slice(dot + 1).split('.').filter(Boolean);
  }
  const el = document.createElement(name);
  if (classes.length) el.className = classes.join(' ');
  if (props && (typeof props !== 'object' || props instanceof Node || Array.isArray(props))) {
    children.unshift(props);
    props = null;
  }
  if (props) {
    for (const [key, value] of Object.entries(props)) {
      if (value === undefined || value === null || value === false) continue;
      if (key === 'class') el.className = [el.className, value].filter(Boolean).join(' ');
      else if (key === 'style' && typeof value === 'object') {
        for (const [sk, sv] of Object.entries(value)) {
          if (sv === undefined || sv === null) continue;
          if (sk.startsWith('--')) el.style.setProperty(sk, sv);
          else el.style[sk] = sv;
        }
      } else if (key.startsWith('on') && typeof value === 'function') {
        el.addEventListener(key.slice(2).toLowerCase(), value);
      } else if (key === 'html') {
        el.innerHTML = value; // only used with trusted, static SVG markup
      } else if (value === true) {
        el.setAttribute(key, '');
      } else {
        el.setAttribute(key, String(value));
      }
    }
  }
  appendChildren(el, children);
  return el;
}

function appendChildren(el, children) {
  for (const child of children) {
    if (child === null || child === undefined || child === false) continue;
    if (Array.isArray(child)) appendChildren(el, child);
    else if (child instanceof Node) el.appendChild(child);
    else el.appendChild(document.createTextNode(String(child)));
  }
}

/* ---------- Storage ---------- */
const STORE_PREFIX = 'ks.hiculture.';
const storage = {
  get(key, fallback) {
    try {
      const raw = window.localStorage.getItem(STORE_PREFIX + key);
      return raw === null ? fallback : JSON.parse(raw);
    } catch (e) {
      return fallback;
    }
  },
  set(key, value) {
    try {
      window.localStorage.setItem(STORE_PREFIX + key, JSON.stringify(value));
      return true;
    } catch (e) {
      toast('Your browser blocked saving. Progress will last only for this visit.');
      return false;
    }
  },
  remove(key) {
    try { window.localStorage.removeItem(STORE_PREFIX + key); } catch (e) { /* ignore */ }
  },
  allKeys() {
    const keys = [];
    try {
      for (let i = 0; i < window.localStorage.length; i += 1) {
        const k = window.localStorage.key(i);
        if (k && k.startsWith(STORE_PREFIX)) keys.push(k.slice(STORE_PREFIX.length));
      }
    } catch (e) { /* ignore */ }
    return keys;
  }
};

/* ---------- Hashing & seeded randomness (ported from the Swift app) ---------- */
const FNV_OFFSET = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const MASK64 = 0xffffffffffffffffn;
const utf8 = new TextEncoder();

function fnv1a64(value) {
  let hash = FNV_OFFSET;
  for (const byte of utf8.encode(value)) {
    hash ^= BigInt(byte);
    hash = (hash * FNV_PRIME) & MASK64;
  }
  return hash;
}

function fnv1a64Hex(value) {
  return fnv1a64(value).toString(16);
}

// SeededRandomNumberGenerator: 64-bit LCG; returns UInt64 as BigInt.
class SeededRandom {
  constructor(seed) {
    let s = BigInt.asUintN(64, BigInt(seed));
    this.state = s === 0n ? 0xdeadbeefn : s;
  }
  nextBig() {
    this.state = (6364136223846793005n * this.state + 1442695040888963407n) & MASK64;
    return this.state;
  }
  // Uniform float in [0, 1) from the high 53 bits.
  next() {
    return Number(this.nextBig() >> 11n) / 9007199254740992;
  }
  int(n) {
    return Math.floor(this.next() * n);
  }
}

function shuffled(array, rng) {
  const out = array.slice();
  const random = rng ? () => rng.next() : Math.random;
  for (let i = out.length - 1; i > 0; i -= 1) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

function randomUUID() {
  if (window.crypto && window.crypto.randomUUID) return window.crypto.randomUUID();
  return 'x' + Date.now().toString(36) + Math.random().toString(36).slice(2);
}

/* ---------- Dates ---------- */
const DAY_MS = 86400000;
function dayKey(date = new Date()) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}
function addDays(date, days) {
  const next = new Date(date.getTime());
  next.setDate(next.getDate() + days);
  return next;
}
function parseDate(value) {
  if (!value) return null;
  // Calendar-only dates ("2026-10-20") are local days, not UTC midnight.
  const calendar = typeof value === 'string' && /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (calendar) return new Date(Number(calendar[1]), Number(calendar[2]) - 1, Number(calendar[3]), 12);
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : d;
}
function formatDate(date, withTime) {
  const d = parseDate(date);
  if (!d) return '';
  const opts = withTime
    ? { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }
    : { month: 'short', day: 'numeric', year: 'numeric' };
  return d.toLocaleString(undefined, opts);
}
function percent(fraction) {
  return `${Math.round((fraction || 0) * 100)}%`;
}
function formatTimer(seconds) {
  const s = Math.max(0, Math.floor(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}
function plural(n, one, many) {
  return `${n} ${n === 1 ? one : (many || one + 's')}`;
}

/* ---------- Misc ---------- */
function safeURL(url, allowHttp) {
  if (!url || typeof url !== 'string') return null;
  try {
    const parsed = new URL(url);
    if (parsed.protocol === 'https:' || (allowHttp && parsed.protocol === 'http:')) return parsed.href;
  } catch (e) { /* invalid */ }
  return null;
}
function hostOf(url) {
  try {
    const host = new URL(url).hostname.toLowerCase();
    return host.startsWith('www.') ? host.slice(4) : host;
  } catch (e) {
    return '';
  }
}
function groupBy(list, keyFn) {
  const map = new Map();
  for (const item of list) {
    const key = keyFn(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  }
  return map;
}
function wordCount(text) {
  return (text || '').split(/\s+/).filter(Boolean).length;
}
function debounce(fn, ms) {
  let timer = null;
  const wrapped = (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => { timer = null; fn(...args); }, ms);
  };
  wrapped.flush = (...args) => { if (timer) { clearTimeout(timer); timer = null; fn(...args); } };
  return wrapped;
}

let toastTimer = null;
function toast(message) {
  const root = App.root;
  if (!root) return;
  const existing = root.querySelector('.toast');
  if (existing) existing.remove();
  const el = h('div.toast', { role: 'status' }, message);
  root.appendChild(el);
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.remove(), 3200);
}

