const pendingAssets = {};
function loadDataAsset(key) {
  if (App.data[key]) return Promise.resolve(App.data[key]);
  const registry = window.__KSHC_DATA || {};
  if (registry[key]) {
    App.data[key] = registry[key];
    return Promise.resolve(App.data[key]);
  }
  if (pendingAssets[key]) return pendingAssets[key];
  pendingAssets[key] = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = App.assetURL(DATA_ASSETS[key]);
    script.async = true;
    script.onload = () => {
      const loaded = (window.__KSHC_DATA || {})[key];
      if (loaded) {
        App.data[key] = loaded;
        resolve(loaded);
      } else {
        delete pendingAssets[key];
        reject(new Error(`${DATA_ASSETS[key]} loaded but contained no data`));
      }
    };
    script.onerror = () => {
      delete pendingAssets[key];
      reject(new Error(`Could not load ${DATA_ASSETS[key]}. Check your connection and reload the page.`));
    };
    document.head.appendChild(script);
  });
  return pendingAssets[key];
}

/* ---------- Source quality (SourceQuality.swift) ---------- */
const LOW_TRUST_HOSTS = ['wikipedia.org', 'biography.com', 'openlibrary.org'];
const SCHOLARLY_HOSTS = [
  'plato.stanford.edu', 'ctext.org', 'gutenberg.org', 'classics.mit.edu', 'avalon.law.yale.edu', 'metmuseum.org',
  'si.edu', 'smithsonianmag.com', 'britishmuseum.org', 'bauhaus.de', 'perseus.tufts.edu', 'publicdomainreview.org',
  'researchcatalogue.net', 'daily.jstor.org', 'un.org', 'pdcnet.org', 'tandfonline.com', 'nationalarchives.gov.uk',
  'law.cornell.edu', 'oyez.org', 'calbar.ca.gov', 'courts.ca.gov', 'leginfo.legislature.ca.gov', 'sec.gov',
  'investor.gov', 'federalreserve.gov', 'bls.gov', 'bea.gov', 'loc.gov', 'archives.gov', 'nasa.gov', 'jpl.nasa.gov',
  'esa.int', 'stsci.edu', 'webbtelescope.org', 'ipcc.ch', 'ncbi.nlm.nih.gov', 'pubmed.ncbi.nlm.nih.gov',
  'nationalacademies.org', 'amstat.org', 'oecd.org', 'stlouisfed.org', 'arxiv.org', 'ctbuh.org', 'nature.com', 'who.int',
  'nejm.org', 'thelancet.com', 'jamanetwork.com', 'bmj.com', 'acpjournals.org', 'cell.com', 'science.org', 'plos.org',
  'cochranelibrary.com', 'nih.gov', 'cdc.gov', 'fda.gov', 'medlineplus.gov', 'uspreventiveservicestaskforce.org',
  'aamc.org', 'usmle.org', 'acgme.org', 'nrmp.org'
];
const REFERENCE_HOSTS = ['britannica.com', 'worldhistory.org', 'metmuseum.org', 'moma.org', 'nobelprize.org', 'hbr.org', 'morningstar.com', 'learn.microsoft.com'];

function matchesAny(host, suffixes) {
  return suffixes.some((s) => host === s || host.endsWith('.' + s));
}

const SourceQuality = {
  byName: null,
  scholarlyByName: null,
  index() {
    if (this.byName) return;
    this.byName = {};
    this.scholarlyByName = {};
    for (const source of (App.data.core && App.data.core.feedSources) || []) {
      this.byName[source.name] = Math.max(this.byName[source.name] || 0, source.qualityScore || 1);
      this.scholarlyByName[source.name] = this.scholarlyByName[source.name] || !!source.isScholarly;
    }
  },
  quality(item) {
    this.index();
    if (item.source in this.byName) return Math.min(Math.max(this.byName[item.source], 0.4), 1.6);
    const host = hostOf(item.url);
    if (matchesAny(host, LOW_TRUST_HOSTS)) return 0.9;
    if (host.endsWith('.edu') || host.endsWith('.gov')) return 1.2;
    if (matchesAny(host, SCHOLARLY_HOSTS)) return 1.15;
    if (matchesAny(host, REFERENCE_HOSTS)) return 1.0;
    return 0.95;
  },
  scholarly(item) {
    this.index();
    if (item.source in this.scholarlyByName) return this.scholarlyByName[item.source] ? 1 : 0;
    const host = hostOf(item.url);
    if (matchesAny(host, LOW_TRUST_HOSTS)) return 0.1;
    if (host.endsWith('.edu') || host.endsWith('.gov')) return 1;
    if (matchesAny(host, SCHOLARLY_HOSTS)) return 1;
    if (matchesAny(host, REFERENCE_HOSTS)) return 0.5;
    return 0.3;
  }
};

function uniqueKey(item) {
  return item.url ? item.url : item.id;
}

/* ---------- Live reading feed (nightly GitHub refresh) ---------- */
const FEED_CACHE_KEY = 'feedCache.v1';
const FEED_CACHE_PER_CATEGORY = 40;

function loadCachedFeed() {
  const cached = storage.get(FEED_CACHE_KEY, null);
  if (cached && Array.isArray(cached.items)) {
    App.feed.items = cached.items.map(normalizeFeedItem).filter(Boolean);
    App.feed.generatedAt = cached.generatedAt || null;
    App.feed.fetchedAt = cached.fetchedAt || null;
  }
}

function normalizeFeedItem(item) {
  if (!item || !item.title || !isLearningSubject(item.category)) return null;
  const url = safeURL(item.url, true);
  if (!url || matchesAny(hostOf(url), LOW_TRUST_HOSTS)) return null;
  return {
    id: String(item.id || url),
    title: String(item.title),
    subtitle: item.subtitle || '',
    summary: item.summary || '',
    category: item.category,
    kind: item.kind || 'article',
    source: item.source || hostOf(url),
    url,
    tags: Array.isArray(item.tags) ? item.tags.slice(0, 4) : [],
    readTime: item.readTime || '',
    era: item.era || 'Current',
    publishedAt: item.publishedAt || null,
    locationName: item.locationName || null,
    latitude: typeof item.latitude === 'number' ? item.latitude : null,
    longitude: typeof item.longitude === 'number' ? item.longitude : null,
    isDynamic: true
  };
}

// A copy of the reading feed and law library is bundled with each website
// build, so the page has current reading even before (or without) the
// nightly GitHub refresh.
DATA_ASSETS.feedSnapshot = 'ks-hiculture-feed-v1.js';
DATA_ASSETS.lawSnapshot = 'ks-hiculture-law-library-v1.js';

async function useFeedSnapshot() {
  if (App.feed.items.length || !(App.data.core && App.data.core.hasFeedSnapshot)) return false;
  try {
    const snapshot = await loadDataAsset('feedSnapshot');
    const items = (snapshot.items || []).map(normalizeFeedItem).filter(Boolean);
    if (!items.length || App.feed.items.length) return false;
    App.feed.items = items;
    App.feed.generatedAt = snapshot.generatedAt || null;
    App.feed.snapshot = true;
    return true;
  } catch (error) {
    return false;
  }
}

async function refreshFeed() {
  if (App.feed.state === 'loading') return;
  if (!App.feedURL) {
    if (await useFeedSnapshot()) App.refresh();
    return;
  }
  App.feed.state = 'loading';
  try {
    const response = await fetch(App.feedURL, { cache: 'no-cache' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const payload = await response.json();
    const items = (payload.items || []).map(normalizeFeedItem).filter(Boolean);
    if (!items.length) throw new Error('The feed had no items');
    App.feed.items = items;
    App.feed.generatedAt = payload.generatedAt || null;
    App.feed.fetchedAt = new Date().toISOString();
    App.feed.state = 'current';
    App.feed.error = null;
    App.feed.snapshot = false;
    // Cache a trimmed copy for offline use (localStorage is small).
    const byCategory = groupBy(items, (i) => i.category);
    const trimmed = [];
    for (const list of byCategory.values()) {
      list.sort((a, b) => (parseDate(b.publishedAt) || 0) - (parseDate(a.publishedAt) || 0));
      trimmed.push(...list.slice(0, FEED_CACHE_PER_CATEGORY).map((i) => ({ ...i, summary: (i.summary || '').slice(0, 240) })));
    }
    storage.set(FEED_CACHE_KEY, { items: trimmed, generatedAt: App.feed.generatedAt, fetchedAt: App.feed.fetchedAt });
  } catch (error) {
    App.feed.state = 'failed';
    App.feed.error = error.message;
    await useFeedSnapshot();
  }
  App.refresh();
}

function lawLibraryURL() {
  if (!App.feedURL) return 'snapshot:';
  return App.feedURL.replace(/feed(\.min)?\.json(\?.*)?$/, 'law-library.json');
}

async function refreshLawLibrary(force) {
  const url = lawLibraryURL();
  if (!url || (App.lawLibrary.state === 'loading') || (App.lawLibrary.data && !force)) return;
  App.lawLibrary.state = 'loading';
  App.refresh();
  try {
    if (url === 'snapshot:') throw new Error('no live law library');
    const response = await fetch(url, { cache: force ? 'reload' : 'default' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    App.lawLibrary.data = await response.json();
    App.lawLibrary.state = 'current';
    App.lawLibrary.error = null;
  } catch (error) {
    let snapshot = null;
    if (App.data.core && App.data.core.hasLawSnapshot) {
      try { snapshot = await loadDataAsset('lawSnapshot'); } catch (e) { snapshot = null; }
    }
    if (snapshot) {
      App.lawLibrary.data = snapshot;
      App.lawLibrary.state = 'current';
      App.lawLibrary.error = null;
    } else {
      App.lawLibrary.state = 'failed';
      App.lawLibrary.error = 'Live law updates are unavailable right now. Official links below still work.';
    }
  }
  App.refresh();
}

/* ---------- Content library (ContentLibrary + FeedStore.combined) ---------- */
function evergreenItems() {
  return (App.data.core && App.data.core.evergreen) || [];
}

function combinedItems() {
  const seen = new Set();
  const out = [];
  for (const item of App.feed.items.concat(evergreenItems())) {
    const key = uniqueKey(item);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

/* ---------- Learning content (LearningContentStore) ---------- */
const Learning = {
  merged: null,
  questionsAll() {
    if (this.merged) return this.merged;
    const packs = (App.data.learning && App.data.learning.packs) || [];
    const byID = new Map();
    const order = [];
    for (const pack of packs) {
      for (const q of pack.questions || []) {
        if (!byID.has(q.id)) order.push(q.id);
        byID.set(q.id, q);
      }
    }
    this.merged = order.map((id) => byID.get(id));
    return this.merged;
  },
  packVersion() {
    const packs = (App.data.learning && App.data.learning.packs) || [];
    return packs.length ? packs[packs.length - 1].version : 'bundled';
  },
  isAvailable(q, now = new Date()) {
    if (!isLearningSubject(q.category)) return false;
    if (q.reviewStatus === 'draft') return false;
    if ((q.category === 'law' || q.category === 'investing') && q.reviewStatus !== 'verified') return false;
    if (q.validUntil && new Date(q.validUntil) < now) return false;
    return true;
  },
  questions(category) {
    return this.questionsAll().filter((q) => q.category === category && this.isAvailable(q));
  },
  allCurrent() {
    return this.questionsAll().filter((q) => this.isAvailable(q));
  },
  byID(id) {
    return this.questionsAll().find((q) => q.id === id);
  }
};


/* ---- 30-stores.js ---- */
/* ---------- Settings (AppStorage toggles + CategoryOrderStore) ---------- */
const Settings = {
  state: null,
  load() {
    this.state = storage.get('settings.v1', {});
    if (!this.state.toggles) this.state.toggles = {};
    return this;
  },
  save() { storage.set('settings.v1', this.state); },
  isShown(category) {
    const key = CATEGORY_TOGGLE_KEY[category];
    if (!key) return false;
    return this.state.toggles[key] !== false;
  },
  setShown(category, shown) {
    this.state.toggles[CATEGORY_TOGGLE_KEY[category]] = !!shown;
    this.save();
  },
  categoryOrder() {
    const stored = Array.isArray(this.state.categoryOrder) ? this.state.categoryOrder : [];
    const order = [];
    for (const raw of stored) if (isLearningSubject(raw) && !order.includes(raw)) order.push(raw);
    // Insert any new defaults after the closest preceding default.
    for (const raw of DEFAULT_ORDER) {
      if (order.includes(raw)) continue;
      const index = DEFAULT_ORDER.indexOf(raw);
      const preceding = DEFAULT_ORDER.slice(0, index).reverse().find((c) => order.includes(c));
      if (preceding) order.splice(order.indexOf(preceding) + 1, 0, raw);
      else order.unshift(raw);
    }
    return order;
  },
  setCategoryOrder(order) {
    this.state.categoryOrder = order.slice();
    this.save();
  }
};

/* ---------- Taste profile (TasteStore) ---------- */
const Taste = {
  profile: null,
  load() {
    const stored = storage.get('taste.v1', null);
    this.profile = stored || { categoryWeights: {}, sourceWeights: {}, tagWeights: {}, scholarlyMode: false };
    return this;
  },
  save() { storage.set('taste.v1', this.profile); },
  clamp(v) { return Math.min(Math.max(v, 0.4), 2.2); },
  clampTag(v) { return Math.min(Math.max(v, -0.6), 0.6); },
  weight(category) { return this.profile.categoryWeights[category] ?? 1; },
  apply(item, delta) {
    this.profile.categoryWeights[item.category] = this.clamp(this.weight(item.category) + delta);
    this.profile.sourceWeights[item.source] = this.clamp((this.profile.sourceWeights[item.source] ?? 1) + delta * 0.6);
    for (const tag of item.tags || []) {
      this.profile.tagWeights[tag] = this.clampTag((this.profile.tagWeights[tag] ?? 0) + delta * 0.4);
    }
    this.save();
  },
  like(item) { this.apply(item, 0.08); },
  dislike(item) { this.apply(item, -0.08); },
  reset() {
    const mode = this.profile.scholarlyMode;
    this.profile = { categoryWeights: {}, sourceWeights: {}, tagWeights: {}, scholarlyMode: mode };
    this.save();
  },
  setScholarly(on) { this.profile.scholarlyMode = !!on; this.save(); },
  jitter(seed, id) {
    let hash = seed | 0;
    for (const ch of id) {
      const code = ch.codePointAt(0);
      hash = (code + (hash << 6) + (hash << 16) - hash) | 0;
    }
    return Math.abs(hash % 100) / 1000;
  },
  score(item, seed, now) {
    const categoryWeight = this.weight(item.category);
    const sourceWeight = this.profile.sourceWeights[item.source] ?? 1;
    let tagBoost = 0;
    for (const tag of item.tags || []) tagBoost += this.profile.tagWeights[tag] ?? 0;
    let freshness = 0;
    const published = parseDate(item.publishedAt);
    if (published) {
      const hours = Math.max(1, Math.abs(now - published) / 3600000);
      freshness = Math.min(0.25, 1 / hours);
    }
    const dynamic = item.isDynamic ? 0.12 : 0;
    const quality = SourceQuality.quality(item);
    const scholarlySignal = SourceQuality.scholarly(item);
    const scholarlyBoost = this.profile.scholarlyMode ? (scholarlySignal * 0.3 - (1 - scholarlySignal) * 0.05) : 0;
    const base = categoryWeight * 0.6 + sourceWeight * 0.3 + tagBoost + freshness + dynamic;
    return base * quality + scholarlyBoost + this.jitter(seed, item.id);
  },
  ranked(items, seed) {
    const now = Date.now();
    return items
      .map((item) => ({ item, s: this.score(item, seed, now) }))
      .sort((a, b) => b.s - a.s)
      .map((x) => x.item);
  },
  select(items, count, seed, avoiding) {
    if (!items.length) return [];
    if (!avoiding || !avoiding.size) return this.ranked(items, seed).slice(0, count);
    const fresh = this.ranked(items.filter((i) => !avoiding.has(uniqueKey(i))), seed);
    if (fresh.length >= count) return fresh.slice(0, count);
    const fallback = this.ranked(items.filter((i) => avoiding.has(uniqueKey(i))), seed);
    return fresh.concat(fallback.slice(0, count - fresh.length));
  }
};

/* ---------- Daily seed + content history ---------- */
const DailySeed = {
  today() {
    const stored = storage.get('dailySeed.v1', null);
    const today = dayKey();
    if (stored && stored.date === today && stored.seed) {
      this.record(stored.seed, today);
      return stored.seed;
    }
    const seed = 100000 + Math.floor(Math.random() * 900000);
    storage.set('dailySeed.v1', { date: today, seed });
    this.record(seed, today);
    return seed;
  },
  reroll() {
    const seed = 100000 + Math.floor(Math.random() * 900000);
    storage.set('dailySeed.v1', { date: dayKey(), seed });
    this.record(seed, dayKey());
    return seed;
  },
  history(limit = 14) {
    return storage.get('seedHistory.v1', []).slice(0, limit);
  },
  record(seed, date) {
    const history = storage.get('seedHistory.v1', []);
    if (history[0] && history[0].date === date && history[0].seed === seed) return;
    const next = [{ date, seed }].concat(history.filter((h) => h.date !== date)).slice(0, 30);
    storage.set('seedHistory.v1', next);
  }
};

const ContentHistory = {
  recentIDs(days) {
    const history = storage.get('contentHistory.v1', []);
    const today = dayKey();
    const cutoff = dayKey(addDays(new Date(), -days));
    const ids = new Set();
    for (const snap of history) {
      if (snap.date === today || snap.date < cutoff) continue;
      for (const id of snap.ids) ids.add(id);
    }
    return ids;
  },
  record(ids) {
    const today = dayKey();
    const history = storage.get('contentHistory.v1', []).filter((s) => s.date !== today);
    history.unshift({ date: today, ids: Array.from(new Set(ids)) });
    storage.set('contentHistory.v1', history.slice(0, 30));
  }
};

/* ---------- Section engagement (SectionEngagementStore) ---------- */
const Engagement = {
  state: null,
  load() {
    this.state = storage.get('engagement.v1', { openCounts: {}, openedByDay: {} });
    return this;
  },
  openCount(category) { return Math.max(0, this.state.openCounts[category] || 0); },
  recordOpen(category, items) {
    this.state.openCounts[category] = this.openCount(category) + 1;
    if (items && items.length) {
      const today = dayKey();
      const opened = new Set(this.state.openedByDay[today] || []);
      for (const item of items) opened.add(uniqueKey(item));
      this.state.openedByDay[today] = Array.from(opened).sort();
      const keep = Object.keys(this.state.openedByDay).sort().reverse().slice(0, 30);
      for (const key of Object.keys(this.state.openedByDay)) if (!keep.includes(key)) delete this.state.openedByDay[key];
      ContentHistory.record(Array.from(opened));
    }
    storage.set('engagement.v1', this.state);
  }
};

/* ---------- Saved library (SavedItem) ---------- */
const Saved = {
  items: null,
  load() { this.items = storage.get('saved.v1', []); return this; },
  save() { storage.set('saved.v1', this.items); },
  isSaved(id) { return this.items.some((s) => s.contentId === id); },
  toggle(item) {
    if (this.isSaved(item.id)) {
      this.items = this.items.filter((s) => s.contentId !== item.id);
      this.save();
      toast('Removed from Library');
      return false;
    }
    this.items.unshift({
      contentId: item.id, title: item.title, subtitle: item.subtitle || '', summary: item.summary || '',
      category: cat(item.category).label, categoryRaw: item.category, source: item.source || '', url: item.url || '',
      dateSaved: new Date().toISOString()
    });
    this.save();
    Taste.like(item);
    toast('Saved to Library');
    return true;
  },
  remove(contentId) {
    this.items = this.items.filter((s) => s.contentId !== contentId);
    this.save();
  }
};

/* ---------- Learning progress (LearningProgressStore) ---------- */
function freshCard(now) {
  return { repetitions: 0, intervalDays: 0, easeFactor: 2.5, dueDate: now.toISOString(), lastReviewed: null, totalAttempts: 0, totalCorrect: 0 };
}

const LearningProgress = {
  state: null,
  load() {
    this.state = storage.get('learningProgress.v1', null) || { schemaVersion: 1, attempts: {}, cardStates: {}, essayDrafts: {} };
    return this;
  },
  persist() { storage.set('learningProgress.v1', this.state); },
  attemptsList(category) {
    const all = Object.values(this.state.attempts).sort((a, b) => (a.answeredAt < b.answeredAt ? -1 : 1));
    return category ? all.filter((a) => a.category === category) : all;
  },
  relatedQuestionIDs(category, conceptID) {
    const ids = new Set();
    for (const a of Object.values(this.state.attempts)) {
      if (a.category === category && a.conceptID === conceptID) ids.add(a.questionID);
    }
    return ids;
  },
  recordMCQ(question, selectedChoiceID, confidence, packVersion) {
    const correctID = question.correctChoiceID;
    if (question.type !== 'multipleChoice' || !correctID) return null;
    const now = new Date();
    const attempt = {
      id: randomUUID(), questionID: question.id, category: question.category, conceptID: question.conceptID,
      dimension: question.dimension, selectedChoiceID, correct: selectedChoiceID === correctID,
      confidence: Math.min(Math.max(confidence, 0), 3), answeredAt: now.toISOString(),
      packVersion: packVersion || 'bundled', countsTowardMastery: question.reviewStatus !== 'pilot'
    };
    this.state.attempts[attempt.id] = attempt;
    if (attempt.countsTowardMastery) {
      const related = this.relatedQuestionIDs(question.category, question.conceptID);
      let card = null;
      for (const id of related) {
        const c = this.state.cardStates[id];
        if (c && (!card || (c.lastReviewed || '') > (card.lastReviewed || ''))) card = c;
      }
      card = card ? { ...card } : freshCard(now);
      for (const id of related) delete this.state.cardStates[id];
      LearningProgress.update(card, attempt.correct, attempt.confidence, now);
      this.state.cardStates[question.id] = card;
    }
    this.persist();
    return attempt;
  },
  update(card, correct, confidence, now) {
    const bounded = Math.min(Math.max(confidence, 0), 3);
    const quality = correct ? 3 + (bounded * 2) / 3 : 1 + bounded / 3;
    card.lastReviewed = now.toISOString();
    card.totalAttempts += 1;
    if (correct) { card.totalCorrect += 1; card.repetitions += 1; } else { card.repetitions = 0; }
    if (!correct || card.repetitions <= 1) card.intervalDays = 1;
    else if (card.repetitions === 2) card.intervalDays = confidence === 0 ? 3 : 6;
    else card.intervalDays = Math.max(1, Math.round(card.intervalDays * card.easeFactor * (0.85 + bounded * 0.1)));
    card.easeFactor = Math.max(1.3, card.easeFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)));
    card.dueDate = addDays(now, card.intervalDays).toISOString();
  },
  essayDraft(questionID) { return this.state.essayDrafts[questionID] || null; },
  saveEssayDraft(question, response) {
    const existing = this.state.essayDrafts[question.id];
    this.state.essayDrafts[question.id] = {
      questionID: question.id, category: question.category, conceptID: question.conceptID,
      response, coachingOptIn: false, updatedAt: new Date().toISOString(), coaching: existing ? existing.coaching : null
    };
    return this.persist();
  },
  recordEssayGrade(question, grade) {
    const draft = this.state.essayDrafts[question.id];
    if (!draft) return false;
    draft.coaching = {
      summary: grade.summary, strengths: grade.strengths, nextSteps: grade.nextSteps, sourceChecks: grade.sourceChecks,
      coachedAt: new Date().toISOString(), coachVersion: grade.version, score: grade.score, band: grade.band.label
    };
    return this.persist();
  },
  hasAttemptedID(questionID) {
    return !!this.state.cardStates[questionID] || !!this.state.essayDrafts[questionID]
      || Object.values(this.state.attempts).some((a) => a.questionID === questionID);
  },
  hasAttempted(question) {
    return Object.values(this.state.attempts).some((a) => a.category === question.category && a.conceptID === question.conceptID);
  },
  hasScoredAttempt(question) {
    for (const id of this.relatedQuestionIDs(question.category, question.conceptID)) if (this.state.cardStates[id]) return true;
    return false;
  },
  cardFor(question) {
    let best = null;
    for (const id of this.relatedQuestionIDs(question.category, question.conceptID)) {
      const c = this.state.cardStates[id];
      if (c && (!best || c.dueDate < best.dueDate)) best = c;
    }
    return best;
  },
  isDue(question, now = new Date()) {
    const card = this.cardFor(question);
    return !!card && new Date(card.dueDate) <= now;
  },
  dueQuestions(questions, now = new Date()) {
    const groups = groupBy(questions.filter((q) => this.isDue(q, now)), (q) => `${q.category}::${q.conceptID}`);
    return Array.from(groups.values()).map((variants) => variants.reduce((a, b) => {
      if (a.generatedAt === b.generatedAt) return a.id < b.id ? b : a;
      return a.generatedAt < b.generatedAt ? b : a;
    }));
  },
  dueCount(questions, now) { return this.dueQuestions(questions, now).length; },
  score(attempts) {
    if (!attempts.length) return 0;
    return (attempts.filter((a) => a.correct).length + 1) / (attempts.length + 2);
  },
  masterySummary(category, questions) {
    const relevantQ = questions.filter((q) => !category || q.category === category);
    const relevantA = this.attemptsList().filter((a) => (!category || a.category === category) && a.countsTowardMastery);
    const scores = {};
    for (const d of DIMENSIONS) scores[d] = this.score(relevantA.filter((a) => a.dimension === d));
    const concepts = new Set(relevantQ.map((q) => `${q.category}::${q.conceptID}`).concat(relevantA.map((a) => `${a.category}::${a.conceptID}`)));
    const correct = relevantA.filter((a) => a.correct).length;
    const summary = {
      attemptedCount: relevantA.length,
      correctCount: correct,
      dueCount: this.dueCount(relevantQ),
      conceptCount: concepts.size,
      dimensionScores: scores,
      accuracy: relevantA.length ? correct / relevantA.length : 0
    };
    const values = Object.values(scores);
    summary.masteryScore = values.reduce((a, b) => a + b, 0) / values.length;
    let weakest = null;
    for (const d of DIMENSIONS) {
      if (!weakest || scores[d] < scores[weakest] || (scores[d] === scores[weakest] && d < weakest)) weakest = d;
    }
    summary.weakestDimension = weakest;
    return summary;
  },
  questionMastery(question) {
    const matching = Object.values(this.state.attempts).filter((a) => a.category === question.category && a.conceptID === question.conceptID && a.countsTowardMastery);
    if (!matching.length) return 0;
    return (matching.filter((a) => a.correct).length + 1) / (matching.length + 2);
  },
  hasDimensionPractice(dimension, category) {
    return Object.values(this.state.attempts).some((a) => a.dimension === dimension && (!category || a.category === category));
  },
  reset() {
    this.state = { schemaVersion: 1, attempts: {}, cardStates: {}, essayDrafts: {} };
    this.persist();
  }
};

/* ---------- MCQ trainer progress (LawMCQProgressStore / MedicalMCQProgressStore) ---------- */
class MCQProgress {
  constructor(key, bankVersion) {
    this.key = key;
    this.bankVersion = bankVersion;
    this.state = storage.get(key, null) || { attempts: {}, exposed: [] };
    this.exposed = new Set(this.state.exposed);
    this.rebuild();
  }
  persist() {
    this.state.exposed = Array.from(this.exposed);
    storage.set(this.key, this.state);
  }
  rebuild() {
    const stats = { totalAttempted: 0, totalCorrect: 0, currentStreak: 0, bestStreak: 0, subjectStats: {}, cardStates: {} };
    const ordered = Object.values(this.state.attempts).sort((a, b) => (a.answeredAt === b.answeredAt ? (a.id < b.id ? -1 : 1) : (a.answeredAt < b.answeredAt ? -1 : 1)));
    for (const attempt of ordered) {
      stats.totalAttempted += 1;
      if (attempt.correct) {
        stats.totalCorrect += 1;
        stats.currentStreak += 1;
        stats.bestStreak = Math.max(stats.bestStreak, stats.currentStreak);
      } else {
        stats.currentStreak = 0;
      }
      const subject = stats.subjectStats[attempt.subject] || { attempted: 0, correct: 0 };
      subject.attempted += 1;
      if (attempt.correct) subject.correct += 1;
      stats.subjectStats[attempt.subject] = subject;
      const answeredAt = new Date(attempt.answeredAt);
      const card = stats.cardStates[attempt.questionID] || { repetitions: 0, intervalDays: 0, easeFactor: 2.5, dueDate: attempt.answeredAt, lastReviewed: null, correctStreak: 0, totalAttempts: 0, totalCorrect: 0 };
      MCQProgress.schedule(card, attempt.correct, answeredAt);
      stats.cardStates[attempt.questionID] = card;
    }
    this.stats = stats;
  }
  // SpacedReviewScheduler.update
  static schedule(card, correct, date) {
    const quality = correct ? 4 : 2;
    card.lastReviewed = date.toISOString();
    card.totalAttempts += 1;
    if (correct) card.totalCorrect += 1;
    card.correctStreak = correct ? card.correctStreak + 1 : 0;
    card.repetitions = correct ? card.repetitions + 1 : 0;
    if (card.repetitions <= 1) card.intervalDays = 1;
    else if (card.repetitions === 2) card.intervalDays = 6;
    else card.intervalDays = Math.max(1, Math.round(card.intervalDays * card.easeFactor));
    card.easeFactor = Math.max(1.3, card.easeFactor + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02)));
    card.dueDate = addDays(date, card.intervalDays).toISOString();
  }
  get accuracyPercent() {
    return this.stats.totalAttempted ? Math.round((this.stats.totalCorrect / this.stats.totalAttempted) * 100) : 0;
  }
  hasAttempts(subject) { return (this.stats.subjectStats[subject]?.attempted || 0) > 0; }
  subjectAccuracy(subject) {
    const s = this.stats.subjectStats[subject];
    return s && s.attempted ? Math.round((s.correct / s.attempted) * 100) : 0;
  }
  hasSeen(id) { return this.exposed.has(id) || !!this.stats.cardStates[id]; }
  unseen(questions) { return questions.filter((q) => !this.hasSeen(q.id)); }
  dueQuestions(questions, now = new Date()) {
    return questions.filter((q) => {
      const card = this.stats.cardStates[q.id];
      return card && new Date(card.dueDate) <= now;
    });
  }
  dueCount(questions) { return this.dueQuestions(questions).length; }
  // Count due cards without needing the bank loaded (home screen badges).
  dueCountAll(now = new Date()) {
    return Object.values(this.stats.cardStates).filter((c) => new Date(c.dueDate) <= now).length;
  }
  leastRecentlyReviewed(questions, excluding) {
    return questions.filter((q) => !excluding.has(q.id)).sort((a, b) => {
      const la = this.stats.cardStates[a.id]?.lastReviewed || '';
      const lb = this.stats.cardStates[b.id]?.lastReviewed || '';
      if (la === lb) return a.id < b.id ? -1 : 1;
      return la < lb ? -1 : 1;
    });
  }
  markExposed(ids) {
    let changed = false;
    for (const id of ids) if (!this.exposed.has(id)) { this.exposed.add(id); changed = true; }
    if (changed) this.persist();
  }
  record(question, correct, mode, focus) {
    const attempt = {
      id: randomUUID(), questionID: question.id, subject: question.subject, correct,
      answeredAt: new Date().toISOString(), mode, focus: focus || null, bankVersion: this.bankVersion
    };
    this.state.attempts[attempt.id] = attempt;
    this.exposed.add(question.id);
    this.rebuild();
    this.persist();
  }
  reset() {
    this.state = { attempts: {}, exposed: [] };
    this.exposed = new Set();
    this.rebuild();
    this.persist();
  }
}

let LawProgress = null;
let MedProgress = null;

function loadStores() {
  Settings.load();
  Taste.load();
  Engagement.load();
  Saved.load();
  LearningProgress.load();
  LawProgress = new MCQProgress('lawMCQ.v1', 'law-mcq-v2');
  MedProgress = new MCQProgress('medicalMCQ.v1', 'medical-mcq-v1');
}

function exportProgress() {
  const payload = { app: 'HiCulture web', exportedAt: new Date().toISOString(), version: App.version, data: {} };
  for (const key of storage.allKeys()) {
    if (key === FEED_CACHE_KEY) continue;
    payload.data[key] = storage.get(key, null);
  }
  return payload;
}

function importProgress(payload) {
  if (!payload || payload.app !== 'HiCulture web' || typeof payload.data !== 'object') {
    throw new Error('That file is not a HiCulture web backup.');
  }
  for (const [key, value] of Object.entries(payload.data)) storage.set(key, value);
  loadStores();
}


/* ---- 40-logic.js ---- */
/* ---------- DailyLearningPlanner ---------- */
const Planner = {
  rankCache: new Map(),
  rank(value, salt, date) {
    const key = `${dayKey(date)}::${salt}::${value}`;
    let cached = this.rankCache.get(key);
    if (cached === undefined) {
      if (this.rankCache.size > 20000) this.rankCache.clear();
      cached = fnv1a64(key);
      this.rankCache.set(key, cached);
    }
    return cached;
  },
  compareRank(a, b, salt, date) {
    const ra = this.rank(a, salt, date);
    const rb = this.rank(b, salt, date);
    return ra < rb ? -1 : ra > rb ? 1 : 0;
  },
  oneQuestionPerConcept(questions, salt, date) {
    const groups = groupBy(questions, (q) => `${q.category}::${q.conceptID}`);
    const out = [];
    for (const variants of groups.values()) {
      variants.sort((a, b) => {
        if (a.generatedAt !== b.generatedAt) return a.generatedAt > b.generatedAt ? -1 : 1;
        return this.compareRank(a.id, b.id, salt, date);
      });
      out.push(variants[0]);
    }
    return out;
  },
  needsInitialScoredAttempt(q) {
    if (q.reviewStatus === 'pilot') return !LearningProgress.hasAttemptedID(q.id);
    return !LearningProgress.hasScoredAttempt(q);
  },
  plan(category, questions, limit = 6, date = new Date()) {
    const eligible = questions.filter((q) => q.category === category && Learning.isAvailable(q, date));
    const mcq = this.oneQuestionPerConcept(eligible.filter((q) => q.type === 'multipleChoice'), category, date);
    const essays = eligible.filter((q) => q.type === 'essay');
    const dueIDs = new Set(mcq.filter((q) => LearningProgress.isDue(q, date)).map((q) => q.id));
    const selected = [];
    const selectedIDs = new Set();
    const essaySlots = essays.length && limit >= 3 ? 1 : 0;
    const mcqLimit = limit - essaySlots;
    const append = (list, reason) => {
      for (const q of list) {
        if (selected.length >= mcqLimit) break;
        if (selectedIDs.has(q.id)) continue;
        selectedIDs.add(q.id);
        selected.push({ question: q, reason });
      }
    };
    const due = mcq.filter((q) => dueIDs.has(q.id)).sort((a, b) => {
      const da = LearningProgress.cardFor(a)?.dueDate || '';
      const db = LearningProgress.cardFor(b)?.dueDate || '';
      if (da === db) return this.compareRank(a.id, b.id, category, date);
      return da < db ? -1 : 1;
    });
    append(due, 'dueReview');
    const initial = mcq
      .filter((q) => this.needsInitialScoredAttempt(q) && !selectedIDs.has(q.id))
      .sort((a, b) => this.compareRank(a.id, b.id, `new-${category}`, date));
    append(initial.filter((q) => LearningProgress.hasAttempted(q)), 'unscoredPractice');
    append(initial.filter((q) => !LearningProgress.hasAttempted(q)), 'newConcept');
    if (essaySlots) {
      const essay = essays.slice().sort((a, b) => {
        const da = LearningProgress.essayDraft(a.id);
        const db = LearningProgress.essayDraft(b.id);
        if (!!da !== !!db) return da ? 1 : -1;
        const ta = da?.updatedAt || '';
        const tb = db?.updatedAt || '';
        if (ta === tb) return this.compareRank(a.id, b.id, `essay-${category}`, date);
        return ta < tb ? -1 : 1;
      })[0];
      if (essay) { selected.push({ question: essay, reason: 'synthesis' }); selectedIDs.add(essay.id); }
    }
    if (!selected.length && essays.length) selected.push({ question: essays[0], reason: 'synthesis' });
    return {
      id: `daily::${category}::${dayKey(date)}`,
      items: selected,
      questions: selected.map((s) => s.question),
      dueCount: due.length,
      newCount: selected.filter((s) => s.reason === 'newConcept').length,
      estimatedMinutes: selected.reduce((t, s) => t + (s.question.type === 'essay' ? 12 : 2), 0)
    };
  },
  worldlyPriority(q, dueIDs) {
    if (dueIDs.has(q.id)) return [0, LearningProgress.questionMastery(q)];
    if (this.needsInitialScoredAttempt(q)) return [1, 0];
    if (LearningProgress.hasScoredAttempt(q)) return [2, LearningProgress.questionMastery(q)];
    return [3, 0];
  },
  worldly(questions, limit = 10, date = new Date()) {
    const current = questions.filter((q) => q.type === 'multipleChoice' && Learning.isAvailable(q, date));
    const candidates = this.oneQuestionPerConcept(current, 'worldly', date);
    const eligible = candidates.filter((q) => LearningProgress.isDue(q, date) || this.needsInitialScoredAttempt(q));
    const dueIDs = new Set(eligible.filter((q) => LearningProgress.isDue(q, date)).map((q) => q.id));
    const byCategory = groupBy(eligible, (q) => q.category);
    const order = LEARNING_SUBJECTS.slice().sort((a, b) => this.compareRank(a, b, 'worldly-subject', date));
    const sortByPriority = (list, salt) => list.slice().sort((a, b) => {
      const pa = this.worldlyPriority(a, dueIDs);
      const pb = this.worldlyPriority(b, dueIDs);
      if (pa[0] !== pb[0]) return pa[0] - pb[0];
      if (pa[1] !== pb[1]) return pa[1] - pb[1];
      return this.compareRank(a.id, b.id, salt, date);
    });
    const selected = [];
    const selectedIDs = new Set();
    for (const category of order) {
      if (selected.length >= limit) break;
      const list = byCategory.get(category);
      if (!list || !list.length) continue;
      const ranked = sortByPriority(list, `worldly-${category}`);
      selected.push(ranked[0]);
      selectedIDs.add(ranked[0].id);
    }
    if (selected.length < limit) {
      const rest = sortByPriority(eligible.filter((q) => !selectedIDs.has(q.id)), 'worldly-overflow');
      selected.push(...rest.slice(0, limit - selected.length));
    }
    return {
      questions: selected,
      dueCount: eligible.filter((q) => dueIDs.has(q.id)).length,
      newCount: selected.filter((q) => !dueIDs.has(q.id) && !LearningProgress.hasScoredAttempt(q) && !LearningProgress.hasAttempted(q)).length
    };
  }
};

/* ---------- Today's reading selection (TodayView) ---------- */
const TODAY_COUNTS = {
  science: [4, 21], space: [3, 141], philosophy: [3, 31], history: [2, 41], people: [2, 51],
  investing: [2, 151], business: [2, 161], recipe: [1, 71], obscure: [2, 91], literature: [2, 101],
  art: [2, 111], architecture: [2, 121], design: [2, 131], botany: [3, 191]
};

function selectPillarItems(category, pillars, all, seed, avoiding, total = 5) {
  const items = all.filter((i) => i.category === category);
  if (!items.length) return [];
  const selected = [];
  const avoid = new Set(avoiding);
  pillars.forEach((pillar, index) => {
    const pick = Taste.select(items.filter((i) => (i.tags || []).includes(pillar)), 1, seed + index * 7, avoid);
    selected.push(...pick);
    pick.forEach((i) => avoid.add(uniqueKey(i)));
  });
  const frontier = Taste.select(items.filter((i) => i.isDynamic), 1, seed + 37, avoid);
  selected.push(...frontier);
  frontier.forEach((i) => avoid.add(uniqueKey(i)));
  const remaining = total - selected.length;
  if (remaining > 0) selected.push(...Taste.select(items, remaining, seed + 43, avoid));
  return selected;
}

function selectLawItems(all, seed, avoiding) {
  const items = all.filter((i) => i.category === 'law');
  if (!items.length) return [];
  const isPastExam = (i) => i.id === 'law-bar-past-exams' || /past exams|selected answers/i.test(i.title);
  let selected = Taste.select(items.filter((i) => i.kind === 'essay'), 2, seed + 3, avoiding);
  const avoid = new Set(avoiding);
  selected.forEach((i) => avoid.add(uniqueKey(i)));
  const past = Taste.select(items.filter(isPastExam), 1, seed + 5, avoid);
  selected = selected.concat(past);
  past.forEach((i) => avoid.add(uniqueKey(i)));
  const briefs = Taste.select(items.filter((i) => i.kind === 'caseBrief'), 3, seed + 7, avoid);
  selected = selected.concat(briefs);
  selected.forEach((i) => avoid.add(uniqueKey(i)));
  const remaining = 6 - selected.length;
  if (remaining > 0) selected = selected.concat(Taste.select(items, remaining, seed + 11, avoid));
  return selected;
}

function todayItems(category, seed) {
  const all = combinedItems();
  const recent = ContentHistory.recentIDs(7);
  if (category === 'biotechnology') return selectPillarItems('biotechnology', ['foundations', 'tools', 'applications', 'responsibility'], all, seed + 171, recent);
  if (category === 'medicine') return selectPillarItems('medicine', ['evidence', 'breakthroughs', 'training', 'practice'], all, seed + 181, recent, 6);
  if (category === 'law') return selectLawItems(all, seed + 61, recent);
  const spec = TODAY_COUNTS[category];
  if (!spec) return [];
  return Taste.select(all.filter((i) => i.category === category), spec[0], seed + spec[1], recent);
}

/* ---------- MCQ selection shared by the law and medical trainers ---------- */
const MIX_WEIGHTS = {
  foundation: { easy: 0.5, medium: 0.4, hard: 0.1 },
  balanced: { easy: 0.2, medium: 0.55, hard: 0.25 },
  challenge: { easy: 0.1, medium: 0.45, hard: 0.45 }
};
const MIX_LABEL = { foundation: 'Foundation', balanced: 'Balanced', challenge: 'Challenge' };
const MIX_DESCRIPTION = {
  foundation: 'Easy-heavy mix to build confidence.',
  balanced: 'Balanced distribution across difficulty.',
  challenge: 'Harder mix to stress-test recall.'
};
const DIFFICULTIES = ['easy', 'medium', 'hard'];

function mixTargets(total, mix) {
  const weights = MIX_WEIGHTS[mix];
  const raw = DIFFICULTIES.map((d) => [d, total * weights[d]]);
  const counts = {};
  let allocated = 0;
  for (const [d, r] of raw) { counts[d] = Math.floor(r); allocated += counts[d]; }
  let remainder = total - allocated;
  raw.sort((a, b) => (b[1] - Math.floor(b[1])) - (a[1] - Math.floor(a[1])));
  let i = 0;
  while (remainder > 0) { counts[raw[i % raw.length][0]] += 1; remainder -= 1; i += 1; }
  return counts;
}

function weightedSelection(pool, count, mix) {
  if (count <= 0) return [];
  const targets = mixTargets(count, mix);
  const grouped = groupBy(pool, (q) => q.difficulty);
  const selected = [];
  const used = new Set();
  for (const d of DIFFICULTIES) {
    const picks = shuffled(grouped.get(d) || []).slice(0, targets[d]);
    picks.forEach((q) => { selected.push(q); used.add(q.id); });
  }
  if (selected.length < count) {
    selected.push(...shuffled(pool.filter((q) => !used.has(q.id))).slice(0, count - selected.length));
  }
  return shuffled(selected);
}

const MBE_GROUPS = [['civilProcedure'], ['constitutionalLaw'], ['contracts'], ['criminalLaw', 'criminalProcedure'], ['evidence'], ['realProperty'], ['torts']];

function blueprintSelection(pool, count, mix) {
  const groups = shuffled(MBE_GROUPS);
  const base = Math.floor(count / groups.length);
  const remainder = count % groups.length;
  const selected = [];
  groups.forEach((subjects, index) => {
    const target = base + (index < remainder ? 1 : 0);
    const groupPool = pool.filter((q) => subjects.includes(q.subject));
    selected.push(...weightedSelection(groupPool, Math.min(target, groupPool.length), mix));
  });
  if (selected.length < count) {
    const used = new Set(selected.map((q) => q.id));
    selected.push(...shuffled(pool.filter((q) => !used.has(q.id))).slice(0, count - selected.length));
  }
  return shuffled(selected);
}

function reshuffleChoices(q) {
  const indexed = q.choices.map((text, i) => ({ text, i }));
  const order = shuffled(indexed);
  return { ...q, choices: order.map((c) => c.text), correctIndex: order.findIndex((c) => c.i === q.correctIndex) };
}

/* ---------- Law practice daily exam ---------- */
function dailyExam(seed) {
  const exams = (App.data.core && App.data.core.lawPractice.exams) || [];
  if (!exams.length) return null;
  const rng = new SeededRandom(seed);
  return exams[rng.int(exams.length)];
}


/* ---- 45-essay-grader.js ---- */
/* ---------- On-device essay grader (EssayGrader.swift) ---------- */
// Grades a draft against the question's rubric with no network and no model.
// Each rubric criterion carries `keyPoints` (the distinct ideas a good answer
// states) and `pitfalls` (common wrong claims). The matching rules are the
// ones documented in tools/essay_keypoint_check.py; EssayGrader.swift is a
// line-for-line port, and tools/test_essay_grader.mjs checks the two agree.
const ESSAY_GRADER_VERSION = 'rubric-keypoints-v2';

const ESSAY_BANDS = [
  { id: 'strong', label: 'Strong', min: 85 },
  { id: 'proficient', label: 'Proficient', min: 70 },
  { id: 'developing', label: 'Developing', min: 50 },
  { id: 'emerging', label: 'Emerging', min: 25 },
  { id: 'notYet', label: 'Not yet', min: 0 }
];
const ESSAY_LEVELS = ['Not yet', 'Emerging', 'Developing', 'Proficient', 'Strong'];

const ESSAY_STOPWORDS = new Set(('a about above after again against all also an and any are as at be because been before being below between both but by can could did do does doing down ' +
  'during each either even every few for from further had has have having he her here hers him his how however i if in into is it its just may might more most much must my no nor not of off on once one only ' +
  'or other our out over own rather same she should so some such than that the their them then there these they this those through to too under until up very was we were what when where whether which while who ' +
  'whom why will with within without would you your yours states state explains explain describes describe identifies identify notes note uses use using gives give makes make shows show').split(' '));

const EssayText = {
  normalize(text) {
    return String(text || '')
      .normalize('NFKD').replace(/[̀-ͯ]/g, '')
      .toLowerCase()
      .replace(/[‘’']/g, '')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim().replace(/ +/g, ' ');
  },
  // Split on newlines, and on whitespace that follows . ! or ?
  rawSentences(draft) {
    const out = [];
    for (const line of String(draft || '').split(/\n+/)) {
      let start = 0;
      for (let i = 0; i < line.length; i += 1) {
        const ch = line[i];
        if ((ch === '.' || ch === '!' || ch === '?') && i + 1 < line.length && /\s/.test(line[i + 1])) {
          out.push(line.slice(start, i + 1));
          let j = i + 1;
          while (j < line.length && /\s/.test(line[j])) j += 1;
          start = j;
          i = j - 1;
        }
      }
      if (start < line.length) out.push(line.slice(start));
    }
    return out;
  },
  // [{ raw, norm }] for sentences of at least three words.
  sentences(draft) {
    const out = [];
    for (const raw of this.rawSentences(draft)) {
      const norm = this.normalize(raw);
      if (norm && norm.split(' ').length >= 3) out.push({ raw: raw.trim(), norm });
    }
    return out;
  },
  // A window is one sentence, two adjacent sentences, or three adjacent
  // sentences totalling 50 words or fewer.
  windows(sents) {
    const wins = sents.map((s, i) => ({ text: s.norm, first: i }));
    for (let i = 0; i + 1 < sents.length; i += 1) wins.push({ text: `${sents[i].norm} ${sents[i + 1].norm}`, first: i });
    for (let i = 0; i + 2 < sents.length; i += 1) {
      const joined = `${sents[i].norm} ${sents[i + 1].norm} ${sents[i + 2].norm}`;
      if (joined.split(' ').length <= 50) wins.push({ text: joined, first: i });
    }
    return wins;
  },
  // The term's words must match consecutive words of the text. The last
  // word matches as a prefix (exactly, when the term ends with "$"); earlier
  // words match as prefixes when they have four or more letters.
  termMatches(term, windowText) {
    const whole = term.endsWith('$');
    const normalized = this.normalize(whole ? term.slice(0, -1) : term);
    if (!normalized) return false;
    const needle = normalized.split(' ');
    const text = windowText.split(' ');
    const last = needle.length - 1;
    for (let start = 0; start + needle.length <= text.length; start += 1) {
      let ok = true;
      for (let offset = 0; offset <= last; offset += 1) {
        const have = text[start + offset];
        const word = needle[offset];
        const hit = offset === last
          ? (whole ? have === word : have.startsWith(word))
          : (word.length >= 4 ? have.startsWith(word) : have === word);
        if (!hit) { ok = false; break; }
      }
      if (ok) return true;
    }
    return false;
  },
  patternMatches(pattern, windowText) {
    for (const group of pattern.match || []) {
      if (!group.some((t) => this.termMatches(t, windowText))) return false;
    }
    return !(pattern.avoid || []).some((t) => this.termMatches(t, windowText));
  },
  // Index of the first window that satisfies the pattern, or -1.
  firstMatch(pattern, wins) {
    for (let i = 0; i < wins.length; i += 1) if (this.patternMatches(pattern, wins[i].text)) return i;
    return -1;
  },
  words(text) {
    const norm = this.normalize(text);
    return norm ? norm.split(' ') : [];
  },
  shingles(wordList, size) {
    const set = new Set();
    for (let i = 0; i + size <= wordList.length; i += 1) set.add(wordList.slice(i, i + size).join(' '));
    return set;
  }
};

const ESSAY_REASONING = ['because', 'therefore', 'thus', 'hence', 'consequently', 'as a result', 'which means', 'this means', 'so that', 'since', 'implies', 'it follows', 'leads to', 'that is why', 'for this reason', 'in turn', 'explains why'];
const ESSAY_SUPPORT = ['for example', 'for instance', 'such as', 'e g', 'according to', 'specifically', 'in particular', 'in the case of', 'consider', 'evidence', 'study', 'data', 'measured', 'experiment'];
const ESSAY_LIMITS = ['however', 'although', 'though', 'but', 'on the other hand', 'yet', 'while', 'whereas', 'critics', 'objection', 'limitation', 'limits', 'uncertain', 'does not show', 'does not prove', 'may', 'might', 'could', 'unless', 'caveat', 'trade off', 'tradeoff', 'still', 'alternatively', 'nevertheless', 'that said'];

function essayCountCues(normText, cues) {
  const padded = ` ${normText} `;
  let n = 0;
  for (const cue of cues) {
    let start = 0;
    for (;;) {
      const index = padded.indexOf(` ${cue} `, start);
      if (index < 0) break;
      n += 1;
      start = index + cue.length + 1;
    }
  }
  return n;
}

// Coverage estimate for a criterion that ships without key points (for
// example a pack from an older server): share of the description's
// distinctive words that appear in the draft.
function essayEstimateCoverage(criterion, normDraft) {
  const stems = new Set();
  for (const word of EssayText.words(`${criterion.title} ${criterion.description}`)) {
    if (word.length >= 5 && !ESSAY_STOPWORDS.has(word)) stems.add(word.slice(0, 6));
  }
  if (!stems.size) return 0;
  const padded = ` ${normDraft} `;
  let hit = 0;
  for (const stem of stems) if (padded.includes(` ${stem}`)) hit += 1;
  return Math.min(1, (hit / stems.size) / 0.6);
}

function essayLevel(coverage) {
  if (coverage >= 0.85) return 4;
  if (coverage >= 0.65) return 3;
  if (coverage >= 0.4) return 2;
  if (coverage >= 0.15) return 1;
  return 0;
}

function essayBand(score) {
  return ESSAY_BANDS.find((b) => score >= b.min) || ESSAY_BANDS[ESSAY_BANDS.length - 1];
}

function essayQuote(raw) {
  const text = raw.replace(/\s+/g, ' ').trim();
  return text.length > 180 ? `${text.slice(0, 177).trimEnd()}…` : text;
}

function gradeEssay(question, draft) {
  const allSents = EssayText.sentences(draft);
  const draftWords = EssayText.words(draft);
  const wordTotal = draftWords.length;

  // Sentences lifted from the prompt or its planning questions earn nothing:
  // drop any sentence of 8+ words whose four-word runs mostly come straight
  // from that text.
  const promptShingles = new Set();
  for (const source of [question.prompt].concat(question.coachingPrompts || [])) {
    for (const sh of EssayText.shingles(EssayText.words(source), 4)) promptShingles.add(sh);
  }
  let copied = 0;
  const sents = allSents.filter((s) => {
    const list = s.norm.split(' ');
    if (list.length < 8) return true;
    const own = EssayText.shingles(list, 4);
    let shared = 0;
    for (const sh of own) if (promptShingles.has(sh)) shared += 1;
    if (own.size && shared / own.size >= 0.6) { copied += 1; return false; }
    return true;
  });
  const wins = EssayText.windows(sents);
  const normDraft = sents.map((s) => s.norm).join(' ');

  const rubric = question.rubric || [];
  const weightTotal = rubric.reduce((n, c) => n + (c.weight || 0), 0) || 1;
  let weighted = 0;
  let pointsCovered = 0;
  let pointsTotal = 0;

  const criteria = rubric.map((criterion) => {
    const points = criterion.keyPoints || [];
    const covered = [];
    const missing = [];
    let coverage;
    const estimated = points.length === 0;
    if (estimated) {
      coverage = essayEstimateCoverage(criterion, normDraft);
    } else {
      let got = 0;
      let total = 0;
      for (const point of points) {
        const w = point.weight || 1;
        total += w;
        const at = EssayText.firstMatch(point, wins);
        if (at >= 0) {
          got += w;
          covered.push({ id: point.id, label: point.label, evidence: essayQuote(sents[wins[at].first].raw), weight: w });
        } else {
          missing.push({ id: point.id, label: point.label, hint: point.hint, weight: w });
        }
      }
      coverage = total ? got / total : 0;
      pointsCovered += covered.length;
      pointsTotal += points.length;
    }
    const pitfalls = [];
    for (const pitfall of criterion.pitfalls || []) {
      const at = EssayText.firstMatch(pitfall, wins);
      if (at >= 0) pitfalls.push({ note: pitfall.note, evidence: essayQuote(sents[wins[at].first].raw) });
    }
    const penalty = Math.min(0.4, 0.2 * pitfalls.length);
    const adjusted = Math.max(0, coverage - penalty);
    weighted += adjusted * (criterion.weight || 0) / weightTotal;
    const level = essayLevel(adjusted);
    return {
      id: criterion.id, title: criterion.title, weight: criterion.weight || 0,
      coverage: adjusted, percent: Math.round(adjusted * 100), level, levelLabel: ESSAY_LEVELS[level], estimated,
      covered, missing, pitfalls,
      question: (criterion.coachingQuestions && criterion.coachingQuestions[0]) || ''
    };
  });

  const score = Math.round(weighted * 100);
  const band = essayBand(score);

  // Writing checks: reported next to the rubric score, not folded into it.
  const sentenceCount = sents.length;
  const avgSentence = sentenceCount ? Math.round(sents.reduce((n, s) => n + s.norm.split(' ').length, 0) / sentenceCount) : 0;
  const reasoning = essayCountCues(normDraft, ESSAY_REASONING);
  const support = essayCountCues(normDraft, ESSAY_SUPPORT) + (String(draft).match(/\d+/g) || []).length;
  const limits = essayCountCues(normDraft, ESSAY_LIMITS);
  const paragraphs = String(draft).split(/\n\s*\n|\n/).filter((p) => p.trim().length > 0).length;
  const openingWins = EssayText.windows(sents.slice(0, 2));
  const opensOnPoint = rubric.some((c) => (c.keyPoints || []).some((p) => EssayText.firstMatch(p, openingWins) >= 0));
  const per100 = (n) => (wordTotal ? n / (wordTotal / 100) : 0);
  const checks = [
    { id: 'length', label: 'Length', ok: wordTotal >= 150 && wordTotal <= 600,
      detail: wordTotal < 150 ? `${wordTotal} words. Complete answers to this prompt usually need 200–400.` : wordTotal > 600 ? `${wordTotal} words. Tighten toward 400 so the main line of reasoning stands out.` : `${wordTotal} words, enough room to cover the rubric.` },
    { id: 'opening', label: 'Gets to the point', ok: opensOnPoint,
      detail: opensOnPoint ? 'Your opening sentences already engage a rubric idea.' : 'Open with your answer to the prompt, then support it. The first two sentences do not yet touch a rubric idea.' },
    { id: 'reasoning', label: 'Shows reasoning', ok: per100(reasoning) >= 1,
      detail: per100(reasoning) >= 1 ? `${reasoning} linking phrases (because, therefore, which means…) connect claims to reasons.` : 'Few linking phrases (because, therefore, which means). Say why each claim follows, not only that it is so.' },
    { id: 'support', label: 'Specific support', ok: support >= 2,
      detail: support >= 2 ? 'Includes concrete specifics (examples, figures or named evidence).' : 'Add at least one concrete example, figure or named piece of evidence.' },
    { id: 'limits', label: 'Weighs limits or other views', ok: limits >= 2,
      detail: limits >= 2 ? 'Qualifies claims or considers another side.' : 'State a limit, exception or opposing view and answer it.' },
    { id: 'organization', label: 'Organization', ok: sentenceCount >= 5 && avgSentence <= 32 && (paragraphs >= 2 || wordTotal < 220),
      detail: sentenceCount < 5 ? 'Only a few sentences. Develop each idea in its own sentence.' : avgSentence > 32 ? `Sentences average ${avgSentence} words. Split the longest ones.` : (paragraphs < 2 && wordTotal >= 220) ? 'One long block. Break it into paragraphs, one job each.' : 'Sentences and paragraphs are a readable length.' }
  ];
  if (copied > 0) {
    checks.push({ id: 'ownWords', label: 'Your own words', ok: false,
      detail: `${copied} ${copied === 1 ? 'sentence repeats' : 'sentences repeat'} the prompt and earned no credit. Answer it instead of restating it.` });
  }

  const strengths = [];
  for (const c of criteria) {
    if (c.level >= 3) strengths.push(c.estimated ? `${c.title}: well covered.` : `${c.title}: ${c.covered.length} of ${c.covered.length + c.missing.length} key points covered.`);
  }
  for (const check of checks) if (check.ok && strengths.length < 4 && ['reasoning', 'support', 'limits'].includes(check.id)) strengths.push(check.detail);
  if (!strengths.length) strengths.push(`You have a ${wordTotal}-word draft to build on.`);

  const nextSteps = [];
  for (const c of criteria) for (const p of c.pitfalls) nextSteps.push(p.note);
  const gaps = [];
  for (const c of criteria) for (const m of c.missing) gaps.push({ rank: c.weight * m.weight, hint: m.hint });
  gaps.sort((a, b) => b.rank - a.rank);
  for (const gap of gaps) if (nextSteps.length < 5 && gap.hint) nextSteps.push(gap.hint);
  for (const c of criteria) if (c.estimated && c.level < 3 && nextSteps.length < 5 && c.question) nextSteps.push(c.question);
  for (const check of checks) if (!check.ok && nextSteps.length < 6) nextSteps.push(check.detail);

  const summary = pointsTotal
    ? `Rubric score ${score} of 100 (${band.label}). Your draft covers ${pointsCovered} of ${pointsTotal} key points across ${criteria.length} rubric criteria.`
    : `Rubric score ${score} of 100 (${band.label}), estimated from the rubric descriptions.`;

  return {
    version: ESSAY_GRADER_VERSION, score, band, words: wordTotal, pointsCovered, pointsTotal,
    criteria, checks, strengths, nextSteps, summary,
    sourceChecks: (question.sources || []).map((src) => `Check claims attributed to ${src.publisher} against “${src.title}” before treating them as settled.`),
    disclaimer: 'Scored on this device by matching your draft to the rubric’s key points. It can miss an idea phrased in an unusual way, so treat the score as a guide and confirm facts in the linked sources.'
  };
}


/* ---- 50-ui.js ---- */
/* ---------- Router ---------- */
// Routes live in the URL hash so the browser back button works:
// #/today, #/c/<category>, #/session/<category>, #/essay/<id>, #/worldly,
// #/progress, #/sources, #/library, #/settings, #/law/mcq, #/law/library,
// #/medicine/mcq, #/item/<id>
const Router = {
  routes: [],
  current: null,
  add(pattern, render, opts = {}) {
    const keys = [];
    const regex = new RegExp('^' + pattern.replace(/:([a-zA-Z]+)/g, (_, k) => { keys.push(k); return '([^/]+)'; }) + '$');
    this.routes.push({ regex, keys, render, opts });
  },
  parse() {
    const raw = (window.location.hash || '').replace(/^#/, '');
    const [path, query] = raw.split('?');
    const params = new URLSearchParams(query || '');
    const clean = path && path.startsWith('/') ? path : '/today';
    for (const route of this.routes) {
      const m = clean.match(route.regex);
      if (m) {
        const args = {};
        route.keys.forEach((k, i) => { args[k] = decodeURIComponent(m[i + 1]); });
        params.forEach((v, k) => { args[k] = v; });
        return { route, args, path: clean };
      }
    }
    return { route: this.routes[0], args: {}, path: '/today' };
  },
  go(path) {
    if (window.location.hash === '#' + path) App.refresh();
    else window.location.hash = path;
  },
  back(fallback = '/today') {
    if (App.navDepth > 0) window.history.back();
    else this.go(fallback);
  }
};

// Per-route ephemeral state (quiz sessions, drafts) survives re-renders.
const ScreenState = new Map();
function screenState(key, init) {
  if (!ScreenState.has(key)) ScreenState.set(key, init());
  return ScreenState.get(key);
}

/* ---------- Shell ---------- */
const TABS = [
  { id: 'today', label: 'Today', icon: 'sparkles', path: '/today' },
  { id: 'progress', label: 'Progress', icon: 'chart', path: '/progress' },
  { id: 'sources', label: 'Sources', icon: 'globe', path: '/sources' },
  { id: 'courses', label: 'Courses', icon: 'graduation', path: '/courses' },
  { id: 'library', label: 'Library', icon: 'books', path: '/library' }
];

function renderShell(screen, meta) {
  const app = h('div.app', { class: meta.homeBackground ? 'home' : '' });
  app.appendChild(h('div.backdrop', { 'aria-hidden': 'true' }, h('i.b1'), h('i.b2'), h('i.b3'), h('i.ring')));

  const left = meta.back
    ? h('button.round-btn', { type: 'button', 'aria-label': 'Back', onclick: () => Router.back(meta.backFallback) }, icon('back'))
    : h('a.round-btn', { href: App.homeURL, 'aria-label': 'Back to kylesalaya.com', title: 'kylesalaya.com', target: '_top' }, icon('home'));
  const right = meta.right || (meta.showSettings
    ? h('button.round-btn.gold', { type: 'button', 'aria-label': 'Learning settings', onclick: () => Router.go('/settings') }, icon('sliders'))
    : h('span.spacer44'));
  const bar = h('header.topbar', left, h('div.title', meta.title || ''), right);
  app.appendChild(bar);

  const main = h('main.screen', { id: 'hc-main', tabindex: '-1' }, screen);
  app.appendChild(main);

  const tab = meta.tab || 'today';
  app.appendChild(h('nav.tabbar', { 'aria-label': 'HiCulture sections' },
    TABS.map((t) => h('a', { href: '#' + t.path, 'aria-current': t.id === tab ? 'page' : null }, icon(t.icon), t.label))
  ));
  return app;
}

/* ---------- Shared components ---------- */
function sectionHeader(title, subtitle) {
  return h('div.section-header', h('h2.section-title', title), subtitle ? h('p.subhead', subtitle) : null);
}

function card(accent, ...children) {
  return h('section.card', { style: { '--accent': accent } }, ...children);
}

function metric(value, label, iconName) {
  return h('div.metric', { role: 'group', 'aria-label': `${label}: ${value}` },
    iconName ? icon(iconName) : null, h('span.v', String(value)), h('span.l', label));
}

function statPill(title, value) {
  return h('div.stat', h('span.t', title), h('span.v', String(value)));
}

function pill(iconName, text) {
  return h('span.pill', iconName ? icon(iconName) : null, text);
}

function button(label, opts = {}) {
  const el = h(`${opts.href ? 'a' : 'button'}.btn.${opts.kind || 'primary'}`, {
    type: opts.href ? null : 'button',
    href: opts.href || null,
    target: opts.href && opts.external ? '_blank' : null,
    rel: opts.href && opts.external ? 'noopener' : null,
    style: { '--accent': opts.accent || THEME.sunsetGold },
    disabled: opts.disabled || null,
    'aria-label': opts.ariaLabel || null,
    class: opts.block ? 'block' : null,
    onclick: opts.disabled ? null : opts.onClick
  }, opts.icon ? icon(opts.icon) : null, label);
  return el;
}

function segmented(options, value, onChange, label) {
  return h('div.seg', { role: 'group', 'aria-label': label || null },
    options.map((o) => h('button', {
      type: 'button',
      'aria-pressed': String(o.value === value),
      onclick: () => { if (o.value !== value) onChange(o.value); }
    }, o.label)));
}

function selectMenu(options, value, onChange, label) {
  const sel = h('select.select', { 'aria-label': label || null, onchange: (e) => onChange(e.target.value === '' ? null : e.target.value) },
    options.map((o) => {
      const opt = h('option', { value: o.value ?? '' }, o.label);
      if ((o.value ?? null) === (value ?? null)) opt.selected = true;
      return opt;
    }));
  return sel;
}

function modeRow({ iconName, emoji, title, subtitle, detail, accent, href, onClick, disabled }) {
  const inner = h('div.tile.row', { style: { '--accent': accent, padding: '15px', borderRadius: '20px', background: 'rgba(255,255,255,0.65)' } },
    h('span.icon-circle', { style: { '--accent': accent } }, emoji ? emoji : icon(iconName)),
    h('div.grow.stack.xtight', { style: { gap: '3px' } },
      h('h3.card-title', title),
      subtitle ? h('p.subhead', subtitle) : null,
      detail ? h('p.caption', { style: { color: accent } }, detail) : null),
    h('span.chev', icon('chevronRight')));
  if (disabled) return h('div', { style: { opacity: 0.45 } }, inner);
  return href ? h('a.tap', { href: '#' + href }, inner) : h('button.tap', { type: 'button', onclick: onClick }, inner);
}

function masteryBar(dimension, score, hasPractice, accent) {
  return h('div.stack.xtight', { style: { gap: '6px' }, role: 'group', 'aria-label': `${DIMENSION_LABEL[dimension]}: ${hasPractice ? percent(score) : 'Not practiced'}` },
    h('div.row.between', h('span.subhead', { style: { color: 'var(--night)' } }, DIMENSION_LABEL[dimension]), h('span.caption', hasPractice ? percent(score) : 'Not practiced')),
    h('div.bar', { style: { '--accent': accent } }, h('i', { style: { width: `${(hasPractice ? score : 0) * 100}%` } })));
}

function progressBar(fraction, accent, thick) {
  return h(`div.bar${thick ? '.thick' : ''}`, { style: { '--accent': accent }, role: 'progressbar', 'aria-valuemin': '0', 'aria-valuemax': '100', 'aria-valuenow': String(Math.round(fraction * 100)) },
    h('i', { style: { width: `${Math.max(0, Math.min(1, fraction)) * 100}%` } }));
}

function externalLink(url, label, iconName = 'external', allowHttp) {
  const href = safeURL(url, allowHttp);
  if (!href) return null;
  return h('a.link', { href, target: '_blank', rel: 'noopener' }, icon(iconName), label);
}

function learningSourceRow(source, accent) {
  const href = safeURL(source.url);
  if (!href) return null;
  return h('a.src', { href, target: '_blank', rel: 'noopener', style: { '--accent': accent } },
    h('span.ic', icon(/\.pdf/i.test(source.url) ? 'doc' : 'link')),
    h('div.grow.stack.xtight', { style: { gap: '3px' } },
      h('span.t', source.title),
      h('span.s', `${source.publisher} · ${USAGE_LABEL[source.usage] || 'Source'}`),
      source.evidenceLocator ? h('span.s', { style: { opacity: 0.85 } }, source.evidenceLocator) : null),
    h('span.out', icon('external')));
}

// SourceBriefRow + a bookmark button (the iOS Library had no save entry point).
function sourceBriefRow(item) {
  const href = safeURL(item.url, true);
  if (!href) return null;
  const accent = cat(item.category).accent;
  const saved = Saved.isSaved(item.id);
  const saveBtn = h('button.icon-btn.save', {
    type: 'button',
    class: saved ? 'on' : null,
    'aria-label': saved ? 'Remove from Library' : 'Save to Library',
    'aria-pressed': String(saved),
    onclick: (e) => { e.preventDefault(); e.stopPropagation(); Saved.toggle(item); App.refresh(); }
  }, icon(saved ? 'bookmarkFill' : 'bookmark'));
  const link = h('a.src', { href, target: '_blank', rel: 'noopener', style: { '--accent': accent, paddingRight: '46px' } },
    h('span.ic', cat(item.category).emoji),
    h('div.grow.stack.xtight', { style: { gap: '4px' } },
      h('span.t', item.title),
      item.summary ? h('span.s', item.summary) : null,
      h('span.p', [item.source, item.publishedAt ? formatDate(item.publishedAt) : null].filter(Boolean).join(' · '))),
    h('span.out', { style: { position: 'absolute', right: '16px', top: '16px' } }, icon('external')));
  return h('div.src-wrap', link, saveBtn);
}

function categoryBadge(raw) {
  return h('span.badge', { style: { '--accent': cat(raw).accent } }, cat(raw).label);
}

function disclosure(summary, ...content) {
  return h('details.disclosure', h('summary', summary), h('div.content', ...content));
}

function emptyCard(accent, title, text) {
  return card(accent, h('h3.card-title', title), h('p.body', text));
}


/* ---- 60-views-learning.js ---- */
/* ---------- Today ---------- */
function visibleCategories() {
  return Settings.categoryOrder().filter((c) => isLearningSubject(c) && Settings.isShown(c));
}

function dueCountFor(category) {
  let due = LearningProgress.dueCount(Learning.questions(category));
  if (category === 'law') due += LawProgress.dueCountAll();
  if (category === 'medicine') due += MedProgress.dueCountAll();
  return due;
}

function homeGrid(categories) {
  const base = Object.fromEntries(categories.map((c, i) => [c, i]));
  const due = Object.fromEntries(categories.map((c) => [c, dueCountFor(c)]));
  const opens = Object.fromEntries(categories.map((c) => [c, Engagement.openCount(c)]));
  const ranked = categories.slice().sort((a, b) => (due[b] - due[a]) || (opens[b] - opens[a]) || (base[a] - base[b]));
  return h('div.bento', ranked.map((c) => {
    const openCount = opens[c];
    const normalized = Math.min(Math.max(0, openCount), 40) / 40;
    const growth = normalized * (2 - normalized);
    const mass = 1 + 1.65 * growth;
    const phase = Math.abs(Array.from(c).reduce((acc, ch) => (acc * 31 + ch.charCodeAt(0)) | 0, 17) % 628) / 100;
    const wide = openCount >= 8;
    const meta = cat(c);
    return h('a.home-card', {
      href: `#/c/${c}`,
      class: wide ? 'span2' : null,
      style: {
        '--h': `${150 + 78 * growth}px`, '--r': `${32 - 8 * growth}px`, '--accent': meta.accent,
        '--amp': `${(3.7 / Math.sqrt(mass)).toFixed(2)}px`, '--dur': `${(13.6 * Math.sqrt(mass)).toFixed(1)}s`, '--delay': `-${(phase * 2.2).toFixed(2)}s`
      },
      'aria-label': `${meta.home}. ${due[c] ? `${due[c]} review questions due` : 'Daily practice ready'}`
    },
    h('span.art', { style: { backgroundImage: `url("${cardImageURL(c)}")` }, 'aria-hidden': 'true' }),
    h('span.meta', h('span.chip', due[c] ? `${due[c]} DUE` : 'DAILY PRACTICE'), h('span.name', meta.home)));
  }));
}

function renderToday() {
  const categories = visibleCategories();
  return h('div.stack',
    h('a.tap', { href: '#/worldly' },
      card(THEME.sunsetGold,
        h('div.row.top', { style: { gap: '12px' } },
          h('span.icon-circle', { style: { '--accent': THEME.sapphire, background: 'rgba(255,255,255,0.68)', width: '38px', height: '38px' } }, icon('globe')),
          h('div.grow', h('h3.card-title', 'Worldly Challenge'), h('p.caption', 'Today’s mixed-subject practice')),
          h('span.chev', icon('arrowRight'))),
        h('p.subhead', 'Connect ideas across science, history, culture, markets, the arts, and more—then see the reasoning and sources.'),
        h('span.subhead', { style: { color: 'var(--night)', fontWeight: 600, display: 'inline-flex', gap: '6px', alignItems: 'center' } }, icon('play'), 'Start today’s challenge'))),
    h('h2.section-title', { style: { padding: '0 4px' } }, 'Choose a subject'),
    categories.length ? homeGrid(categories) : emptyCard(THEME.stone, 'All subjects are hidden', 'Turn subjects back on in Learning settings.'),
    h('p.footer-note', 'HiCulture · progress is saved privately in this browser. ', h('a', { href: '#/settings' }, 'Back up or restore'), '.'));
}

/* ---------- Category detail ---------- */
function renderCategory({ category }) {
  if (!isLearningSubject(category)) return renderNotFound();
  const items = todayItems(category, App.seed);
  if (category === 'law') return renderLawHub(items);
  return h('div.stack',
    sectionHeader(cat(category).home, cat(category).sub),
    category === 'medicine' ? renderMedicineHub(items) : renderSubjectHub(category, items));
}

/* ---------- Subject hub ---------- */
function practiceSessionIDs(category) {
  const questions = Learning.questions(category);
  const planned = Planner.plan(category, questions, 11).questions.filter((q) => q.type === 'multipleChoice');
  const mcq = questions.filter((q) => q.type === 'multipleChoice');
  return (planned.length ? planned : mcq).slice(0, 10).map((q) => q.id);
}

function renderSubjectHub(category, sourceItems, opts = {}) {
  const accent = cat(category).accent;
  const questions = Learning.questions(category);
  const plan = Planner.plan(category, questions);
  const mastery = LearningProgress.masterySummary(category, questions);
  const mcqCount = Math.min(10, practiceSessionIDs(category).length);
  const essay = plan.questions.find((q) => q.type === 'essay') || questions.find((q) => q.type === 'essay');
  const sources = [];
  const seenURLs = new Set();
  for (const q of questions) for (const s of q.sources) if (!seenURLs.has(s.url)) { seenURLs.add(s.url); sources.push(s); }

  const daily = plan.questions.length
    ? h('a.tap', { href: `#/session/${category}?mode=daily` }, dailyCardBody())
    : h('div', dailyCardBody());
  function dailyCardBody() {
    return card(accent,
      h('div.row.top', { style: { gap: '14px' } },
        h('span.icon-circle.lg', { style: { '--accent': accent } }, icon('graduation')),
        h('div.grow',
          h('h3.card-title', `Today’s ${cat(category).label} Session`),
          h('p.subhead', plan.questions.length ? `${plan.questions.length} prompts · about ${plan.estimatedMinutes} min` : 'New source-backed questions are being prepared.')),
        h('span.chev', { style: { color: accent } }, icon('arrowRight'))),
      plan.questions.length ? h('div.pill-row', pill('refresh', `${plan.dueCount} due`), pill('sparkles', `${plan.newCount} new`), plan.questions.some((q) => q.type === 'essay') ? pill('pencil', 'Essay') : null) : null,
      h('p.caption', 'Retrieval first. Explanations and sources unlock after each answer.'));
  }

  return h('div.stack',
    opts.hideDaily ? null : daily,
    h('div.metrics',
      metric(mastery.attemptedCount, 'Attempts', 'check'),
      metric(mastery.attemptedCount ? percent(mastery.accuracy) : 'New', 'Accuracy', 'scope'),
      metric(mastery.dueCount, 'Due', 'clock')),
    h('div.stack.tight',
      sectionHeader('Practice', 'Choose the kind of thinking you want to train'),
      modeRow({ iconName: 'checklist', title: 'Multiple Choice', subtitle: 'Commit an answer, then study every rationale', detail: `${mcqCount}-question adaptive round`, accent: THEME.tideTeal, href: `/session/${category}?mode=practice`, disabled: !mcqCount }),
      essay ? modeRow({ iconName: 'pencil', title: 'Essay Workshop', subtitle: 'Write an argument and get it graded against a rubric', detail: essayWorkshopDetail(category), accent: THEME.sunsetGold, href: `/essays/${category}` }) : null),
    card(accent,
      h('div.row.between', h('h2.section-title', 'Knowledge Profile'), mastery.attemptedCount && mastery.weakestDimension ? h('span.caption', { style: { color: accent } }, `Focus: ${DIMENSION_LABEL[mastery.weakestDimension]}`) : null),
      h('p.caption', 'Mastery stays separated by the kind of thinking involved. Recognition alone does not stand in for deeper understanding.'),
      DIMENSIONS.map((d) => masteryBar(d, mastery.dimensionScores[d], LearningProgress.hasDimensionPractice(d, category), accent))),
    sources.length ? h('div.stack.tight', sectionHeader('Course Sources', 'The evidence behind today’s practice'), sources.slice(0, 6).map((s) => learningSourceRow(s, accent))) : null,
    sourceItems && sourceItems.length ? h('div.stack.tight', sectionHeader('Read & Apply', 'Current and evergreen source briefs for the next round'), sourceItems.slice(0, 8).map(sourceBriefRow)) : null);
}

/* ---------- Learning session ---------- */
function sessionQuestionIDs(category, mode) {
  if (mode === 'worldly' || mode === 'connection') {
    const plan = Planner.worldly(enabledLearningQuestions());
    let qs = plan.questions;
    if (mode === 'connection') {
      const higher = qs.filter((q) => q.dimension === 'application' || q.dimension === 'synthesis');
      qs = higher.length ? higher : qs;
    }
    return qs.map((q) => q.id);
  }
  if (mode === 'practice') return practiceSessionIDs(category);
  return Planner.plan(category, Learning.questions(category)).questions.map((q) => q.id);
}

function enabledLearningQuestions() {
  return Learning.allCurrent().filter((q) => Settings.isShown(q.category));
}

function displayedChoices(question, salt) {
  let hash = 0xcbf29ce484222325n ^ BigInt(salt);
  for (const byte of utf8.encode(question.id)) { hash ^= BigInt(byte); hash = (hash * FNV_PRIME) & MASK64; }
  return shuffled(question.choices, new SeededRandom(hash));
}

function renderLearningSession({ category, mode = 'daily' }) {
  const isTrivia = mode === 'worldly' || mode === 'connection';
  const key = `session:${category}:${mode}:${dayKey()}`;
  const s = screenState(key, () => ({
    ids: sessionQuestionIDs(category, mode),
    index: 0, selected: {}, committed: {}, confidence: {}, essaysDone: new Set(), complete: false,
    salt: Math.floor(Math.random() * 2 ** 31)
  }));
  const questions = s.ids.map((id) => Learning.byID(id)).filter(Boolean);
  const accent = isTrivia ? THEME.sapphire : cat(category).accent;
  const title = isTrivia ? 'Worldly Challenge' : `${cat(category).label} Practice`;

  if (!questions.length) {
    return h('div.stack', h('h1.hero-title', title),
      card(accent, h('h3.card-title', 'No session is available yet'), h('p.body', 'HiCulture will keep the source library available while a validated question set is prepared.')));
  }

  if (s.complete) {
    const answered = Object.keys(s.committed).length;
    const correct = questions.filter((q) => s.committed[q.id] && s.committed[q.id] === q.correctChoiceID).length;
    return h('div.stack', h('h1.hero-title', title),
      card(THEME.leaf,
        h('span', { style: { color: THEME.leaf, fontSize: '38px', lineHeight: 1 } }, icon('seal')),
        h('h2.section-title', 'Session complete'),
        answered ? h('p.body', `${correct} of ${answered} multiple-choice answers were correct.`) : null,
        s.essaysDone.size ? h('p.body', `${s.essaysDone.size} essay draft ${s.essaysDone.size === 1 ? 'was' : 'were'} added to your private workshop.`) : null,
        h('p.caption', 'The review queue will bring concepts back when retrieval is most useful.'),
        h('div.btn-row',
          button('Done', { accent, onClick: () => { ScreenState.delete(key); Router.back(isTrivia ? '/worldly' : `/c/${category}`); } }),
          button('New round', { kind: 'secondary', accent, onClick: () => { ScreenState.delete(key); App.refresh(); } }))));
  }

  const q = questions[Math.min(s.index, questions.length - 1)];
  const progress = s.index / questions.length;
  const committed = s.committed[q.id];
  const advance = () => {
    if (s.index + 1 < questions.length) s.index += 1;
    else s.complete = true;
    App.refresh({ scrollTop: true });
  };

  const header = h('div.stack.tight',
    h('h1.hero-title', title),
    h('div.row.between', h('span.subhead', `Prompt ${s.index + 1} of ${questions.length}`), h('span.caption', percent(progress))),
    progressBar(progress, accent));

  const meta = h('div.row.wrap', { style: { gap: '8px' } },
    categoryBadge(q.category), h('span.tag', DIMENSION_LABEL[q.dimension]), h('span.tag', DIFFICULTY_LABEL[q.difficulty]),
    q.reviewStatus === 'pilot' ? h('span.caption', { style: { color: THEME.ember } }, 'Pilot') : null);

  let body;
  if (q.type === 'essay') {
    const draft = LearningProgress.essayDraft(q.id);
    const words = wordCount(draft ? draft.response : '');
    const ready = s.essaysDone.has(q.id) || words >= 40;
    body = h('div.stack.tight',
      h('p.caption', { style: { color: cat(q.category).accent } }, 'Synthesis prompt'),
      h('p.body', 'Write privately, then get a rubric grade on this device and revise.'),
      h('a.tap', { href: `#/essay/${encodeURIComponent(q.id)}` },
        h('div.tile.row', { style: { '--accent': cat(q.category).accent, background: `color-mix(in srgb, ${cat(q.category).accent} 13%, transparent)` } },
          icon('pencil'), h('span.subhead.grow', { style: { color: 'var(--night)' } }, words ? 'Continue Draft' : 'Open Writing Studio'),
          words ? h('span.caption', `${words} words`) : null, h('span.chev', icon('chevronRight')))),
      button(ready ? 'Continue Session' : 'Draft at least 40 words to continue', { accent: cat(q.category).accent, disabled: !ready, onClick: () => { s.essaysDone.add(q.id); advance(); } }));
  } else {
    const choices = displayedChoices(q, s.salt);
    const selectedID = s.selected[q.id];
    const letters = 'ABCDEF';
    body = h('div.stack.tight',
      choices.map((choice, i) => {
        let cls = '';
        if (committed && choice.id === q.correctChoiceID) cls = 'correct';
        else if (committed && committed === choice.id) cls = 'wrong';
        else if (!committed && selectedID === choice.id) cls = 'selected';
        return h('button.choice', {
          type: 'button', class: cls, disabled: committed ? true : null,
          'aria-pressed': String(selectedID === choice.id),
          onclick: () => { s.selected[q.id] = choice.id; App.refresh(); }
        }, h('span.letter', letters[i]), h('span.text', choice.text),
        cls === 'correct' ? h('span.mark', { style: { color: THEME.leaf } }, icon('check')) : cls === 'wrong' ? h('span.mark', { style: { color: THEME.ember } }, icon('x')) : null);
      }),
      committed ? answerFeedback(q, committed, choices) : h('div.stack.tight',
        h('div.stack.xtight', h('p.caption', 'Confidence before feedback'),
          segmented([{ value: 0, label: 'Guess' }, { value: 1, label: 'Unsure' }, { value: 2, label: 'Likely' }, { value: 3, label: 'Sure' }],
            s.confidence[q.id] ?? 2, (v) => { s.confidence[q.id] = v; App.refresh(); }, 'Confidence')),
        button('Commit Answer', {
          accent: cat(q.category).accent, disabled: !selectedID,
          onClick: () => {
            s.committed[q.id] = selectedID;
            LearningProgress.recordMCQ(q, selectedID, s.confidence[q.id] ?? 2, Learning.packVersion());
            App.refresh();
          }
        })),
      committed ? h('div.row', { style: { justifyContent: 'flex-end' } }, button(s.index + 1 === questions.length ? 'Finish Session' : 'Next Prompt', { accent, onClick: advance })) : null);
  }

  return h('div.stack', header,
    card(cat(q.category).accent, meta, h('h2.card-title', { style: { whiteSpace: 'pre-line' } }, q.prompt), body));
}

function answerFeedback(q, selectedID, choices) {
  const correct = selectedID === q.correctChoiceID;
  return h('div.feedback',
    h('div.row', { style: { color: correct ? THEME.leaf : THEME.ember } }, icon(correct ? 'check' : 'refresh'), h('h3.section-title', { style: { color: 'inherit' } }, correct ? 'Correct' : 'Not quite')),
    q.reviewStatus === 'pilot' ? h('p.caption', { style: { color: THEME.ember } }, 'This is a pilot item. Your answer helps you practice, but it is excluded from the mastery profile.') : null,
    h('div.stack.xtight', h('p.subhead', 'Why'), h('p.body', q.explanation)),
    h('hr.divider'),
    h('div.stack.tight', h('p.subhead', { style: { color: 'var(--night)' } }, 'Choice Review'),
      choices.map((c) => h('div.review-row',
        h('span', { style: { color: c.id === q.correctChoiceID ? THEME.leaf : 'rgba(23,23,31,0.38)' } }, icon(c.id === q.correctChoiceID ? 'check' : 'x')),
        h('div.stack.xtight', { style: { gap: '3px' } }, h('p.caption', { style: { color: 'var(--night)' } }, c.text), h('p.caption', { style: { fontWeight: 500 } }, c.rationale))))),
    q.sources.length ? h('div.stack.tight', h('hr.divider'), h('p.subhead', { style: { color: 'var(--night)' } }, 'Verify in the Source'), q.sources.map((src) => learningSourceRow(src, cat(q.category).accent))) : null);
}

/* ---------- Essay workshop ---------- */
const ESSAY_LEVEL_COLORS = [THEME.ember, THEME.copper, THEME.sunsetGold, THEME.tideTeal, THEME.leaf];

function essayGradeCard(q, grade, accent) {
  const scoreColor = ESSAY_LEVEL_COLORS[essayLevel(grade.score / 100)];
  const criterionBlock = (c) => {
    const color = ESSAY_LEVEL_COLORS[c.level];
    return h('div.inset.stack.xtight', { style: { gap: '8px' } },
      h('div.row.between', { style: { alignItems: 'baseline', gap: '8px' } },
        h('span.subhead', { style: { color: 'var(--night)' } }, c.title),
        h('span.caption', { style: { color, whiteSpace: 'nowrap' } }, `${c.levelLabel} · ${c.percent}%`)),
      progressBar(c.coverage, color, true),
      c.pitfalls.map((p) => h('div.stack.xtight', { style: { gap: '2px' } },
        h('p.caption', { style: { color: THEME.ember, display: 'flex', gap: '6px' } }, icon('warning'), h('span', p.note)),
        h('p.caption.quote', `“${p.evidence}”`))),
      c.missing.map((m) => h('div.stack.xtight', { style: { gap: '2px' } },
        h('p.caption', { style: { color: 'rgba(23,23,31,0.82)' } }, `○ Not found: ${m.label}`),
        h('p.caption', { style: { fontWeight: 500, paddingLeft: '18px' } }, m.hint))),
      c.covered.length ? disclosure(`Covered: ${c.covered.length} of ${c.covered.length + c.missing.length}`,
        c.covered.map((p) => h('div.stack.xtight', { style: { gap: '2px', marginTop: '6px' } },
          h('p.caption', { style: { color: 'rgba(23,23,31,0.82)' } }, `✓ ${p.label}`),
          h('p.caption.quote', { style: { paddingLeft: '18px' } }, `“${p.evidence}”`)))) : null,
      (c.estimated && c.question) ? h('p.caption', { style: { fontStyle: 'italic', fontWeight: 500 } }, c.question) : null);
  };
  return card(THEME.leaf,
    h('div.row.between', h('h2.section-title', 'Rubric Grade'), h('span.tag', 'On device')),
    h('div.row.between', { style: { alignItems: 'baseline' }, role: 'group', 'aria-label': `Rubric score ${grade.score} out of 100, ${grade.band.label}` },
      h('div', { style: { display: 'flex', alignItems: 'baseline', gap: '6px' } },
        h('span.essay-score', String(grade.score)), h('span.subhead', '/ 100')),
      h('span.card-title', { style: { color: scoreColor } }, grade.band.label)),
    progressBar(grade.score / 100, scoreColor, true),
    h('p.body', grade.pointsTotal
      ? `Your draft covers ${grade.pointsCovered} of ${grade.pointsTotal} key points across ${grade.criteria.length} rubric criteria.`
      : 'Estimated from the rubric descriptions.'),
    h('div.stack.tight', h('p.subhead', { style: { color: 'var(--night)' } }, 'By Criterion'), grade.criteria.map(criterionBlock)),
    coachingList('Next revision', grade.nextSteps, THEME.sunsetGold),
    coachingList('What is working', grade.strengths, THEME.leaf),
    h('div.stack.xtight', h('p.subhead', { style: { color: 'var(--night)' } }, 'Writing Checks'),
      h('p.caption', 'These describe the writing itself and do not change the rubric score.'),
      grade.checks.map((check) => h('div', { style: { display: 'flex', gap: '8px', alignItems: 'flex-start' } },
        h('span', { style: { color: check.ok ? THEME.leaf : THEME.sunsetGold, flex: 'none', fontWeight: 700 }, 'aria-hidden': 'true' }, check.ok ? '✓' : '!'),
        h('div.stack.xtight', { style: { gap: '1px' } }, h('p.caption', { style: { color: 'var(--night)' } }, check.label), h('p.caption', { style: { fontWeight: 500 } }, check.detail))))),
    coachingList('Source checks', grade.sourceChecks, THEME.tideTeal),
    h('p.caption', grade.disclaimer),
    q.modelOutline.length ? disclosure('Compare your structure', q.modelOutline.map((p) => h('div.list-dot', { style: { '--accent': accent } }, p))) : null);
}

function essayWorkshopDetail(category) {
  const essays = Learning.questions(category).filter((q) => q.type === 'essay');
  const started = essays.filter((q) => LearningProgress.essayDraft(q.id)).length;
  const prompts = plural(essays.length, 'prompt', 'prompts');
  return started ? `${prompts} · ${started} started` : prompts;
}

// Every essay prompt in a subject with its draft and grade status.
function renderEssayList({ category }) {
  if (!isLearningSubject(category)) return renderNotFound();
  const accent = cat(category).accent;
  const essays = Learning.questions(category).filter((q) => q.type === 'essay');
  const status = (q) => {
    const draft = LearningProgress.essayDraft(q.id);
    if (!draft) return ['Not started', 'rgba(23,23,31,0.55)'];
    const words = wordCount(draft.response);
    if (draft.coaching && typeof draft.coaching.score === 'number') return [`Last grade ${draft.coaching.score} · ${draft.coaching.band || essayBand(draft.coaching.score).label} · ${words} words`, accent];
    return [words ? `Draft · ${words} words` : 'Not started', THEME.sunsetGold];
  };
  return h('div.stack',
    h('div.stack.xtight', h('h1.hero-title', 'Essay Workshop'), h('p.body', `${cat(category).label} · choose a prompt. Drafts and grades stay in this browser.`)),
    essays.length ? essays.map((q) => {
      const [text, color] = status(q);
      return h('a.tap', { href: `#/essay/${encodeURIComponent(q.id)}` }, card(accent,
        h('h3.card-title', q.conceptTitle),
        h('p.subhead.clamp3', q.prompt),
        h('span.caption', { style: { color } }, text)));
    }) : emptyCard(THEME.stone, 'No essay prompts yet', 'This subject has multiple-choice practice only.'));
}

function renderEssay({ id }) {
  const q = Learning.byID(id);
  if (!q || q.type !== 'essay') return renderNotFound();
  const accent = cat(q.category).accent;
  const s = screenState(`essay:${id}`, () => ({ draft: LearningProgress.essayDraft(id)?.response || '', feedback: null }));
  const counter = h('span.caption', '');
  const updateCounter = () => { counter.textContent = `${wordCount(s.draft)} words`; };
  updateCounter();
  const save = debounce(() => { LearningProgress.saveEssayDraft(q, s.draft); }, 450);
  const feedbackBtnHolder = h('div');
  const renderFeedbackButton = () => {
    feedbackBtnHolder.replaceChildren(
      button(s.feedback ? 'Grade Again' : 'Grade My Draft', { accent, block: true, disabled: wordCount(s.draft) < 40, onClick: () => {
        save.flush();
        LearningProgress.saveEssayDraft(q, s.draft);
        s.feedback = gradeEssay(q, s.draft);
        LearningProgress.recordEssayGrade(q, s.feedback);
        App.refresh();
      } }),
      h('p.caption', { style: { marginTop: '8px' } }, wordCount(s.draft) < 40 ? 'Write at least 40 words before requesting feedback.' : 'Graded in this browser against the rubric. Nothing is sent anywhere.'));
  };
  renderFeedbackButton();
  const textarea = h('textarea.textarea', {
    'aria-label': 'Essay draft', style: { '--accent': accent },
    oninput: (e) => { s.draft = e.target.value; updateCounter(); save(); renderFeedbackButton(); },
    onblur: () => save.flush()
  });
  textarea.value = s.draft;
  App.onLeave = () => { save.flush(); };

  const fb = s.feedback;
  const saved = LearningProgress.essayDraft(id);
  return h('div.stack',
    h('div.stack.xtight', h('h1.hero-title', 'Essay Workshop'), h('p.subhead', `${cat(q.category).label} · ${q.conceptTitle}`),
      h('p.body', 'Draft privately, then get a rubric grade on this device. Nothing is published.')),
    card(accent,
      h('div.row.between', h('h2.section-title', 'Prompt'), h('span.tag', DIFFICULTY_LABEL[q.difficulty])),
      h('p.card-title', q.prompt),
      q.coachingPrompts.length ? disclosure('Planning questions', q.coachingPrompts.map((p) => h('div.list-dot', { style: { '--accent': accent } }, p))) : null),
    card(THEME.tideTeal,
      h('h2.section-title', 'Research Desk'),
      h('p.caption', 'Open the original sources. When copying is restricted, HiCulture links to the official page or PDF instead.'),
      q.sources.map((src) => learningSourceRow(src, accent))),
    card(THEME.sunsetGold,
      h('div.row.between', h('h2.section-title', 'Your Draft'), counter),
      textarea,
      h('p.caption', { style: { display: 'flex', gap: '6px', alignItems: 'center' } }, icon('lock'), 'Saved privately in this browser. Nothing is published.'),
      feedbackBtnHolder),
    fb ? essayGradeCard(q, fb, accent)
      : (saved && saved.coaching && typeof saved.coaching.score === 'number'
        ? card(THEME.leaf, h('div.row.between', h('h2.section-title', 'Last Grade'), h('span.tag', 'On device')),
          h('p.body', saved.coaching.summary),
          h('p.caption', 'Tap Grade My Draft to see the full breakdown for the current draft.'))
        : null));
}

function coachingList(title, items, accent) {
  if (!items || !items.length) return null;
  return h('div.stack.xtight', h('p.subhead', { style: { color: 'var(--night)' } }, title), items.map((i) => h('div.list-dot', { style: { '--accent': accent } }, i)));
}

