// MedicalBlockSelector: interleave systems, then fill difficulty targets.
function medBlockSelect(pool, count, mix) {
  if (count <= 0 || !pool.length) return [];
  const bySystem = groupBy(shuffled(pool), (q) => q.subject);
  const interleaved = [];
  while (bySystem.size) {
    for (const system of shuffled(Array.from(bySystem.keys()))) {
      const bucket = bySystem.get(system);
      interleaved.push(bucket.shift());
      if (!bucket.length) bySystem.delete(system);
    }
  }
  const selected = [];
  const used = new Set();
  for (const d of DIFFICULTIES) {
    const target = Math.round(count * MIX_WEIGHTS[mix][d]);
    const picks = interleaved.filter((q) => q.difficulty === d && !used.has(q.id)).slice(0, target);
    picks.forEach((q) => { selected.push(q); used.add(q.id); });
  }
  if (selected.length < count) selected.push(...interleaved.filter((q) => !used.has(q.id)).slice(0, count - selected.length));
  return selected.slice(0, count);
}

function renderMedicalMCQ(args) {
  const loading = needsBank('medBank', 'clinical question bank');
  if (loading) return loading;
  const bank = App.data.medBank.questions;
  const ui = screenState('medmcq', () => ({ config: { mode: 'tutor', focus: null, count: 10, system: null, mix: 'balanced' }, session: null, message: null, notice: null, startedReview: false }));
  const cfg = ui.config;
  const systemsFor = (focus) => MED_SYSTEMS.filter(([s]) => bank.some((q) => q.subject === s && (!focus || q.focus.includes(focus))));
  const pool = () => bank.filter((q) => (!cfg.focus || q.focus.includes(cfg.focus)) && (!cfg.system || q.subject === cfg.system));

  const begin = (questions, mode) => {
    const prepared = questions.map(reshuffleChoices);
    MedProgress.markExposed(prepared.map((q) => q.id));
    ui.session = { questions: prepared, mode, focus: cfg.focus, index: 0, answers: {}, recorded: new Set(), complete: false, startedAt: Date.now(), timeLimit: mode === 'timed' ? prepared.length * 90 : null };
    App.refresh({ scrollTop: true });
  };
  const start = (dueOnly) => {
    ui.message = null;
    ui.notice = dueOnly ? 'Due review repeats answered questions whose review date has arrived.' : null;
    let selected;
    if (dueOnly) selected = shuffled(MedProgress.dueQuestions(bank)).slice(0, 40);
    else {
      const p = pool();
      const target = Math.min(cfg.count, p.length);
      selected = medBlockSelect(MedProgress.unseen(p), target, cfg.mix);
      let ids = new Set(selected.map((q) => q.id));
      if (selected.length < target) {
        selected = selected.concat(shuffled(MedProgress.dueQuestions(p).filter((q) => !ids.has(q.id))).slice(0, target - selected.length));
        ids = new Set(selected.map((q) => q.id));
      }
      if (selected.length < target) {
        const recycled = MedProgress.leastRecentlyReviewed(p, ids).slice(0, target - selected.length);
        if (recycled.length) ui.notice = 'You have seen every question for these filters, so the least recently reviewed ones are included.';
        selected = selected.concat(recycled);
      }
      selected = shuffled(selected);
    }
    if (!selected.length) { ui.message = dueOnly ? 'No answered questions are due yet.' : 'No questions match these filters.'; App.refresh(); return; }
    begin(selected, dueOnly ? 'tutor' : cfg.mode);
  };

  if (args.review === '1' && !ui.startedReview && !ui.session) { ui.startedReview = true; start(true); }

  const header = h('div.stack.xtight', h('h1.hero-title', 'Clinical Question Bank'),
    h('p.body', 'Original USMLE-style vignettes by organ system, with tutor explanations, timed blocks, and spaced review.'));

  if (ui.session) return h('div.stack', header, mcqSessionView(ui, {
    progress: MedProgress, accent: THEME.cardinal,
    tags: (q) => [h('span.tag', MED_SYSTEM_LABEL[q.subject] || q.subject), h('span.tag', q.focus.map((f) => MED_FOCUS_LABEL[f] || f).join(' · ')), h('span.tag', q.difficulty[0].toUpperCase() + q.difficulty.slice(1))],
    references: (q) => (q.references || []).map((r) => externalLink(r.url, r.title, 'book')),
    subjectLabel: (s) => MED_SYSTEM_LABEL[s] || s,
    summaryNote: () => null,
    onNew: () => { ui.session = null; ui.notice = null; App.refresh({ scrollTop: true }); },
    onReviewMissed: (missed) => { ui.notice = 'This block repeats questions you missed, in tutor mode.'; begin(missed.map((m) => bank.find((q) => q.id === m.id) || m), 'tutor'); }
  }));

  const due = MedProgress.dueCount(bank);
  return h('div.stack', header,
    card(THEME.cardinal,
      h('h2.section-title', 'Performance Snapshot'),
      h('div.metrics', statPill('Answered', MedProgress.stats.totalAttempted), statPill('Accuracy', MedProgress.stats.totalAttempted ? `${MedProgress.accuracyPercent}%` : 'New'), statPill('Best Streak', MedProgress.stats.bestStreak)),
      h('p.caption', `${bank.length} questions across ${systemsFor(null).length} systems.`)),
    card(THEME.tideTeal,
      h('h2.section-title', 'Spaced Review Queue'),
      h('p.subhead', due ? `${plural(due, 'answered question')} ${due === 1 ? 'is' : 'are'} due for review.` : 'Nothing is due. Missed questions come back the next day; correct ones space out.'),
      h('div', button('Review Due Questions', { kind: 'secondary', accent: THEME.tideTeal, disabled: !due, onClick: () => start(true) }))),
    card(THEME.stone,
      h('h2.section-title', 'Build a Block'),
      segmented(MODE_OPTIONS, cfg.mode, (v) => { cfg.mode = v; App.refresh(); }, 'Mode'),
      h('div', h('p.field-label', 'Exam Focus'),
        segmented([{ value: null, label: 'All' }].concat(MED_FOCUS), cfg.focus, (v) => {
          cfg.focus = v;
          if (cfg.system && !systemsFor(v).some(([s]) => s === cfg.system)) cfg.system = null;
          App.refresh();
        }, 'Exam focus'),
        h('p.caption', { style: { marginTop: '6px' } }, cfg.focus ? MED_FOCUS.find((f) => f.value === cfg.focus).description : 'Mixed blocks across foundations, Step 1 mechanisms, and Step 2 CK management.')),
      h('div', h('p.field-label', 'Questions'), segmented([10, 20, 40].map((n) => ({ value: n, label: String(n) })), cfg.count, (v) => { cfg.count = v; App.refresh(); }, 'Questions')),
      selectMenu([{ value: null, label: 'All Systems' }].concat(systemsFor(cfg.focus).map(([v, l]) => ({ value: v, label: l }))), cfg.system, (v) => { cfg.system = v; App.refresh(); }, 'System'),
      selectMenu(MIX_OPTIONS, cfg.mix, (v) => { cfg.mix = v; App.refresh(); }, 'Difficulty mix'),
      h('p.caption', cfg.mode === 'timed' ? 'Timed blocks give 90 seconds per question, like USMLE pacing, and reveal answers at the end.' : 'Tutor mode locks your answer, then explains the key and the most tempting distractors.'),
      h('div', button('Start Block', { accent: THEME.cardinal, onClick: () => start(false) })),
      ui.message ? h('p.notice', ui.message) : null),
    card(THEME.leaf,
      h('h2.section-title', 'By System'),
      h('div.metrics', { style: { gridTemplateColumns: '1fr 1fr' } },
        systemsFor(null).map(([s, label, emoji]) => h('button.tap', {
          type: 'button', 'aria-label': `Start a block of ${label} questions`,
          onclick: () => { cfg.system = s; cfg.focus = null; start(false); }
        }, h('div.stat', h('span.t', `${emoji} ${label}`), h('span.v', MedProgress.hasAttempts(s) ? `${MedProgress.subjectAccuracy(s)}%` : 'New'))))),
      h('p.caption', { style: { fontWeight: 500 } }, 'Original HiCulture study items for learning. They are not affiliated with the NBME or USMLE and are not medical advice.')));
}


/* ---- 80-views-misc.js ---- */
/* ---------- Sources / Atlas ---------- */
const ERA_SORT = { ancient: -500, classical: -200, medieval: 1200, edo: 1700, 'early modern': 1650, modern: 1950, timeless: 0, 'pre-columbian': -300 };

function eraLabel(era) { return era || 'Timeless'; }
function eraSortKey(era) { const k = (era || '').toLowerCase(); return k in ERA_SORT ? ERA_SORT[k] : 1500; }

let leafletPromise = null;
function loadLeaflet() {
  if (window.L) return Promise.resolve(window.L);
  if (leafletPromise) return leafletPromise;
  leafletPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    script.integrity = 'sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=';
    script.crossOrigin = 'anonymous';
    script.onload = () => resolve(window.L);
    script.onerror = () => { leafletPromise = null; reject(new Error('Map library unavailable')); };
    document.head.appendChild(script);
  });
  return leafletPromise;
}

function renderSources() {
  const ui = screenState('atlas', () => ({ mode: 'map' }));
  const sources = ((App.data.core && App.data.core.feedSources) || []).filter((s) => isLearningSubject(s.category));
  const counts = {};
  for (const item of App.feed.items) counts[item.source] = (counts[item.source] || 0) + 1;

  let body;
  if (ui.mode === 'map') {
    const mapEl = h('div.map', { role: 'region', 'aria-label': 'Map of source locations' });
    loadLeaflet().then((L) => {
      if (!mapEl.isConnected) return;
      const map = L.map(mapEl, { worldCopyJump: true, scrollWheelZoom: false, attributionControl: true }).setView([25, 0], 1);
      L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
        maxZoom: 8,
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'
      }).addTo(map);
      for (const s of sources) {
        const n = counts[s.name] || 0;
        const marker = L.marker([s.latitude, s.longitude], {
          icon: L.divIcon({ className: '', html: `<div class="pin" style="background:${cat(s.category).accent}">${n || ''}</div>`, iconSize: [26, 26], iconAnchor: [13, 13] }),
          title: s.name
        }).addTo(map);
        marker.bindPopup(`<strong>${escapeHTML(s.name)}</strong><br>${escapeHTML(s.region)}<br>${n} items today`);
      }
      setTimeout(() => map.invalidateSize(), 60);
    }).catch(() => { mapEl.replaceChildren(h('p.caption', { style: { padding: '20px' } }, 'The map could not load. The source list below is still available.')); });

    const grouped = groupBy(sources, (s) => s.category);
    body = card(THEME.tideTeal,
      h('h2.section-title', 'World Atlas'),
      h('p.subhead', 'Tap into the geographic origin of today’s knowledge stream.'),
      mapEl,
      LEARNING_SUBJECTS.filter((c) => grouped.has(c)).map((c) => disclosure(`${cat(c).emoji} ${cat(c).label} · ${grouped.get(c).length} sources`,
        grouped.get(c).map((s) => h('div.row.between', { style: { padding: '8px 10px', borderRadius: '14px', background: 'rgba(255,255,255,0.7)' } },
          h('div.stack.xtight', { style: { gap: '2px' } }, h('span.subhead', { style: { color: 'var(--night)' } }, s.name), h('span.caption', s.region)),
          h('span.caption', `${counts[s.name] || 0} items`))))));
  } else {
    const dynamic = App.feed.items.map((i) => ({ item: i, label: formatDate(i.publishedAt), key: (parseDate(i.publishedAt) || new Date(0)).getTime() / 1000 }));
    const ever = evergreenItems().filter((i) => isLearningSubject(i.category)).map((i) => ({ item: i, label: eraLabel(i.era), key: eraSortKey(i.era) }));
    const entries = dynamic.concat(ever).sort((a, b) => b.key - a.key).slice(0, 24);
    body = card(THEME.terraRose,
      h('h2.section-title', 'Timeline Pulse'),
      h('p.subhead', 'A living timeline that stitches today’s headlines to enduring history.'),
      entries.map((e) => card(cat(e.item.category).accent,
        h('div.row.between', categoryBadge(e.item.category), h('span.caption', e.label)),
        h('h3.card-title', e.item.title),
        e.item.summary ? h('p.subhead', { style: { display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden' } }, e.item.summary) : null,
        h('div.row.between', h('span.caption', e.item.source), externalLink(e.item.url, 'Open', 'external', true)))));
  }

  return h('div.stack',
    h('div.stack.xtight', h('h1.hero-title', 'Atlas'), h('p.body', 'Explore where the sources supporting your curriculum come from.')),
    segmented([{ value: 'map', label: 'Map' }, { value: 'timeline', label: 'Timeline' }], ui.mode, (v) => { ui.mode = v; App.refresh(); }, 'View'),
    body);
}

function escapeHTML(text) {
  return String(text).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

